function buildDecisionFrictionMcpEmail({ name, context }) {
  const text = [
    `Hi ${name} team,`,
    `${context}, so a free tool that scores each client email's structure before it ships is a direct fit. It flags subject line, CTA, and message hierarchy weak points in seconds, before your client sees a low open rate and asks why.`,
    'I built this as an MCP tool your team can connect directly to your AI workflow: https://mcp.strategicflow.tech',
    'Run one real client email through it and see what it flags.',
    'Alex Iliescu\nStrategic Flow'
  ].join('\n\n');
  const html = text
    .split(/\n\n/)
    .map(paragraph => `<p>${escapeHtml(paragraph).replace(/\n/g, '<br>')}</p>`)
    .join('\n');
  return { text, html };
}

// ── Global 24-hour email cooldown — monkey-patch resend.emails.send ──────────
// Prevents any two emails going to the same address within 24 hours,
// regardless of which sequence or cron triggered the send.
// Transactional/auth emails (OTPs, verifications, audit results, confirmations)
// and admin/owner addresses are always exempt.
{
  const _origSend = resend.emails.send.bind(resend.emails);
  resend.emails.send = async function patchedSend(params) {
    const {
      _skipGlobalCooldown = false,
      _skipGlobalEmailLog = false,
      ...providerParams
    } = params;
    const toRaw = Array.isArray(providerParams.to) ? providerParams.to[0] : (providerParams.to || '');
    const to    = toRaw.toLowerCase().trim();
    const subj  = providerParams.subject || '';

    const isAdminAddr   = to === OWNER_EMAIL.toLowerCase() || BYPASS_EMAILS.has(to);
    const isTransactional = _skipGlobalCooldown || /verif|management code|you.ve claimed|your.*report|your.*score|demo run|audit lead|new audit|claimed.*✓|ai visibility/i.test(subj);

    if (!isAdminAddr && !isTransactional) {
      if (await isUnsubscribed(to)) {
        console.log(`[global-unsubscribe] blocked → ${to} | subj: "${subj.slice(0,60)}"`);
        return { id: 'unsubscribe-blocked', unsubscribed: true };
      }
      let blocked = false;
      try { blocked = await wasEmailedRecently(to); } catch { /* non-fatal */ }
      if (blocked) {
        console.log(`[24h-cooldown] blocked → ${to} | subj: "${subj.slice(0,60)}"`);
        return { id: 'cooldown-blocked', cooldownBlocked: true };
      }
    }

    const result = await _origSend(providerParams);

    if (!_skipGlobalEmailLog && !isAdminAddr && !result?.error && !result?.cooldownBlocked) {
      recordEmailSent(to, subj).catch(() => {});   // fire-and-forget
    }
    return result;
  };
}

