async function queryGeminiForVisibility(question) {
  const key = process.env.GEMINI_API_KEY;
  if (!key) throw new Error('GEMINI_API_KEY not set');
  const doRequest = async () => fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=${encodeURIComponent(key)}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: question }] }],
        generationConfig: { maxOutputTokens: 1000 }
      }),
      signal: AbortSignal.timeout(25000)
    }
  );
  let apiResp = await doRequest();
  // Retry once on 429 after 15s to ride out transient quota bursts
  if (apiResp.status === 429) {
    await new Promise(r => setTimeout(r, 15000));
    apiResp = await doRequest();
  }
  if (!apiResp.ok) throw new Error(`gemini_http_${apiResp.status}`);
  const data = await apiResp.json();
  const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('gemini_empty_response');
  return text;
}

async function analyzeVisibilityAnswers(companyName, domain, category, knownPositioning, modelAnswers) {
  const answersBlock = modelAnswers.map((a, i) => `Answer ${i + 1}:\n${a}`).join('\n\n');
  const prompt = `Given these 5 AI assistant answers to buyer questions in ${category}, determine
whether ${companyName} (${domain}) was mentioned in any answer (true/false), what position it
held, is the company's description (if any) accurate to its actual positioning as
${knownPositioning || 'a ' + category + ' company'}, and which competitor names appeared instead
or alongside.

POSITION MUST BE DETERMINED PER-ANSWER, THEN THE STRONGEST (BEST) POSITION ACROSS ALL 5 ANSWERS WINS:
- Position is the ORDER IN WHICH ${companyName} IS NAMED relative to other vendors in that
  specific answer's text — the first vendor named in the answer is "1st", the second distinct
  vendor named is "2nd", the third or later is "3rd_plus". Read strictly in the order names
  appear in the text, not by which one the model seems to prefer overall.
- If an answer frames another vendor as the primary/top pick and then names ${companyName}
  afterward — including phrasing like "X is the strongest choice, but ${companyName} is a common
  alternative", "if you want Y instead, ${companyName}...", or any construction where a different
  vendor's name appears first in the text — ${companyName} is NOT "1st" in that answer. Score it
  by its actual named order (2nd, 3rd_plus, etc.), even if the model calls it "the most common
  alternative" or otherwise implies popularity.
- Being named as the ONLY vendor, or being the first vendor name of the answer, is the only way
  to earn "1st" for that answer.

Return ONLY valid JSON, no markdown, no backticks, in this exact shape:
{ "mentioned": <true|false>, "position": "<1st|2nd|3rd_plus|absent>", "description_accuracy": "<pass|weak|fail>", "competitors_shown": [<array of competitor name strings>], "summary_note": "<one sentence>" }

If mentioned is false, position must be "absent" and description_accuracy should reflect that there was nothing to judge (use "fail" only if a wrong/misleading claim was made about the company anyway, otherwise use "weak" as a neutral placeholder — never invent an accuracy verdict for content that doesn't exist).

${answersBlock}`;

  const result = await scoreContentWithClaude(prompt);
  if (typeof result?.mentioned !== 'boolean' || !result.position) {
    throw new Error('analysis_parse_failed');
  }
  return {
    mentioned: result.mentioned,
    position: result.position,
    description_accuracy: result.description_accuracy || null,
    competitors_shown: Array.isArray(result.competitors_shown) ? result.competitors_shown : [],
    summary_note: result.summary_note || ''
  };
}

// Deterministic scoring formula — documented on /ai-visibility/methodology.
// Position: 1st=6, 2nd=4, 3rd_plus=2, absent=0. Accuracy (only if mentioned): pass=4, weak=2, fail=0.
function computeVisibilityModelScore(mentioned, position, descriptionAccuracy) {
  const POSITION_POINTS = { '1st': 6, '2nd': 4, '3rd_plus': 2, 'absent': 0 };
  const ACCURACY_POINTS = { pass: 4, weak: 2, fail: 0 };
  const positionComponent = POSITION_POINTS[position] ?? 0;
  const accuracyComponent = mentioned ? (ACCURACY_POINTS[descriptionAccuracy] ?? 0) : 0;
  return positionComponent + accuracyComponent;
}

// ── IN-MEMORY JOB STORE (for polling-based generation) ──────────────────────
// Each job: { status:'pending'|'complete'|'failed', result, error, created }
const jobs = new Map();
function makeJobId() { return Math.random().toString(36).slice(2,10) + Date.now().toString(36); }

async function setJob(id, data) {
  jobs.set(id, data);
  try {
    await pool.query(`
      INSERT INTO jobs (id, status, result, error, created_at)
      VALUES ($1, $2, $3, $4, NOW())
      ON CONFLICT (id) DO UPDATE SET
        status = $2, result = $3, error = $4
    `, [id, data.status, data.result ? JSON.stringify(data.result) : null, data.error || null]);
  } catch(e) { console.error('[setJob]', e.message); }
}

async function getJob(id) {
  if (jobs.has(id)) return jobs.get(id);
  try {
    const r = await pool.query('SELECT * FROM jobs WHERE id = $1', [id]);
    if (r.rows.length > 0) {
      const row = r.rows[0];
      return { status: row.status, result: row.result ? JSON.parse(row.result) : null, error: row.error };
    }
  } catch(e) { console.error('[getJob]', e.message); }
  return null;
}

// ── URL content cache — 30-min TTL avoids repeat 12s fetches for the same article ──
const urlCache = new Map();
const CACHE_TTL = 1000 * 60 * 30;
async function fetchWithCache(url) {
  const cached = urlCache.get(url);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    console.log('[urlCache] hit:', url);
    return cached.content;
  }
  const content = await fetchPageContent(url);
  urlCache.set(url, { content, timestamp: Date.now() });
  return content;
}
setInterval(() => {
  const cutoff = Date.now() - 30 * 60 * 1000;
  for (const [id, job] of jobs) { if (job.created < cutoff) jobs.delete(id); }
}, 10 * 60 * 1000);

