app.get('/admin/emails.csv', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  try {
    const { rows } = await pool.query(`
      SELECT id, name, url, category,
             contact_email, contact_email_status, contact_email_source,
             contact_email_fetched_at
      FROM directory_listings
      WHERE status='active'
      ORDER BY
        CASE contact_email_status WHEN 'found' THEN 0 ELSE 1 END,
        name
    `);
    const baseUrl = 'https://strategic-flow-audit.replit.app';
    const csvEsc = s => `"${(s||'').replace(/"/g,'""')}"`;
    const header = ['Name','Product URL','ToolIndex Listing','Email','Source Page','Status','Fetched At'].map(csvEsc).join(',');
    const body = rows.map(r => [
      r.name,
      r.url,
      `${baseUrl}/directory?q=${encodeURIComponent(r.name)}`,
      r.contact_email || '',
      r.contact_email_source || '',
      r.contact_email_status || 'pending',
      r.contact_email_fetched_at ? new Date(r.contact_email_fetched_at).toISOString().slice(0,19).replace('T',' ') : '',
    ].map(csvEsc).join(',')).join('\n');

    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="toolindex-contacts.csv"');
    res.send('\uFEFF' + header + '\n' + body); // BOM for Excel
  } catch(e) {
    res.status(500).send('Error: ' + e.message);
  }
});

// ── GET /api/directory/outreach-queue ────────────────────────────────────────
// Returns active + draft listings with contact info for the outreach tracker.
// Fields: id, name, page, cat, email, li, big, emailed_at, status, claimed_at, follow_up_sent_at
app.get('/api/directory/outreach-queue', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  try {
    const base = 'https://strategic-flow-audit.replit.app';
    const { rows } = await pool.query(`
      SELECT dl.id, dl.name, dl.category, dl.status,
             regexp_replace(lower(dl.name), '[^a-z0-9]+', '-', 'g') || '-' || dl.id::text AS slug,
             dl.contact_email, dl.social_linkedin, dl.source,
             dl.outreach_emailed_at, dl.claimed_at, dl.follow_up_sent_at,
             (SELECT COUNT(*) FROM dir_claims dc WHERE dc.listing_id = dl.id) > 0 AS is_claimed
      FROM directory_listings dl
      WHERE dl.status IN ('active', 'draft')
        AND split_part(lower(COALESCE(dl.contact_email,'')), '@', 2) <> ALL($1::text[])
        AND lower(COALESCE(dl.contact_email,'')) <> ALL($2::text[])
      ORDER BY dl.id DESC
    `, [Array.from(DIRECTORY_BLOCKED_DOMAINS), Array.from(DIRECTORY_BLOCKED_EMAILS)]);
    const data = rows.map(r => ({
      id:               String(r.id),
      name:             r.name,
      page:             `${base}/directory/${r.slug}`,
      cat:              r.category || 'Other',
      email:            r.contact_email || '',
      li:               r.social_linkedin || '',
      big:              false,
      status:           r.status || 'active',
      emailed_at:       r.outreach_emailed_at ? r.outreach_emailed_at.toISOString() : null,
      claimed_at:       r.is_claimed ? (r.claimed_at ? r.claimed_at.toISOString() : 'claimed') : null,
      follow_up_sent_at: r.follow_up_sent_at ? r.follow_up_sent_at.toISOString()  : null,
    }));
    res.setHeader('Cache-Control', 'no-store');
    res.json(data);
  } catch(e) {
    console.error('[outreach-queue]', e.message);
    res.status(500).json({ error: 'db_error' });
  }
});

