// ── Unsubscribe helpers — used across all marketing email types ───────────────
function unsubToken(email) {
  return crypto.createHmac('sha256', process.env.SESSION_SECRET || 'sf-unsub-key')
    .update((email || '').toLowerCase().trim()).digest('hex').slice(0, 32);
}
function unsubLink(email) {
  const e = encodeURIComponent((email || '').toLowerCase().trim());
  return `https://strategic-flow-audit.replit.app/unsubscribe?email=${e}&token=${unsubToken(email)}`;
}
async function isUnsubscribed(email) {
  const norm = (email || '').toLowerCase().trim();
  if (!norm) return false;
  if (PERMANENT_OUTREACH_EXCLUSIONS.has(norm)) return true;
  try {
    const { rows } = await pool.query(`SELECT 1 FROM email_unsubscribes WHERE email=$1 LIMIT 1`, [norm]);
    return rows.length > 0;
  } catch { return false; }
}

async function isConfirmedNewsletterContact(email) {
  const norm = (email || '').toLowerCase().trim();
  if (!norm) return false;
  const r = await pool.query(
    `SELECT 1
     FROM toolindex_newsletter_contacts c
     WHERE c.email=$1 AND c.status='confirmed' AND c.confirmed_at IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM email_unsubscribes u WHERE lower(u.email)=lower(c.email)
       )
     LIMIT 1`,
    [norm]
  );
  return r.rows.length > 0;
}

// ── 24-hour global cooldown helpers ─────────────────────────────────────────
// Returns true if `email` received ANY email (non-transactional) in the last 24h.
async function wasEmailedRecently(email, hours = 24) {
  if (!email) return false;
  try {
    const { rows } = await pool.query(
      `SELECT 1 FROM global_email_log
       WHERE lower(email) = $1 AND sent_at > NOW() - ($2 || ' hours')::INTERVAL
       LIMIT 1`,
      [email.toLowerCase().trim(), String(hours)]
    );
    return rows.length > 0;
  } catch { return false; }
}

async function recordEmailSent(email, subject) {
  if (!email) return;
  try {
    await pool.query(
      `INSERT INTO global_email_log (email, email_subject) VALUES ($1, $2)`,
      [email.toLowerCase().trim(), (subject || '').slice(0, 255)]
    );
  } catch { /* non-fatal — never block a send for a log failure */ }
}

function newsletterConfirmTokenHash(token) {
  return crypto.createHash('sha256').update(String(token || '')).digest('hex');
}

async function queueClaimNewsletterConfirmation(email, listingId, { newConsent = false, hookPost = null } = {}) {
  const norm = (email || '').toLowerCase().trim();
  if (!norm || !norm.includes('@')) return { skipped: 'invalid_email' };
  if (isBlockedDirectoryEmail(norm)) return { skipped: 'blocked_email' };

  if (await isUnsubscribed(norm) && !newConsent) {
    await pool.query(
      `INSERT INTO toolindex_newsletter_contacts
         (email, status, source, source_listing_id, consented_at, unsubscribed_at, last_synced_at, updated_at)
       VALUES ($1, 'unsubscribed', 'claim', $2, NOW(), NOW(), NOW(), NOW())
       ON CONFLICT (email) DO UPDATE SET
         status='unsubscribed', unsubscribed_at=COALESCE(toolindex_newsletter_contacts.unsubscribed_at, NOW()),
         source_listing_id=EXCLUDED.source_listing_id, last_synced_at=NOW(), updated_at=NOW()`,
      [norm, listingId || null]
    );
    return { skipped: 'unsubscribed' };
  }

  const existingR = await pool.query(
    `SELECT status, confirmation_sent_at, confirmation_send_reserved_at, confirmation_expires_at
     FROM toolindex_newsletter_contacts WHERE email=$1 LIMIT 1`,
    [norm]
  );
  const existing = existingR.rows[0];
  if (existing?.status === 'confirmed') {
    await pool.query(
      `UPDATE toolindex_newsletter_contacts
       SET source_listing_id=COALESCE($2, source_listing_id), last_synced_at=NOW(), updated_at=NOW()
       WHERE email=$1`,
      [norm, listingId || null]
    );
    return { confirmed: true };
  }
  if (existing?.status === 'unsubscribed' && !newConsent) {
    return { skipped: 'unsubscribed' };
  }
  if (existing?.status === 'pending'
      && existing.confirmation_sent_at
      && existing.confirmation_expires_at
      && new Date(existing.confirmation_expires_at) > new Date()) {
    await pool.query(
      `UPDATE toolindex_newsletter_contacts
       SET source_listing_id=COALESCE($2, source_listing_id), last_synced_at=NOW(), updated_at=NOW()
       WHERE email=$1`,
      [norm, listingId || null]
    );
    return { pending: true, skipped: 'confirmation_already_sent' };
  }
  if (existing?.status === 'pending'
      && existing.confirmation_send_reserved_at
      && new Date(existing.confirmation_send_reserved_at) > new Date(Date.now() - 15 * 60 * 1000)) {
    return { pending: true, skipped: 'confirmation_in_progress' };
  }

  const token = crypto.randomBytes(32).toString('hex');
  const tokenHash = newsletterConfirmTokenHash(token);
  const reservation = await pool.query(
    `INSERT INTO toolindex_newsletter_contacts
       (email, status, source, source_listing_id, consented_at, confirmation_token_hash,
        confirmation_expires_at, confirmation_send_reserved_at, last_synced_at, updated_at)
     VALUES ($1, 'pending', 'claim', $2, NOW(), $3, NOW() + INTERVAL '7 days', NOW(), NOW(), NOW())
     ON CONFLICT (email) DO UPDATE SET
       status='pending', source='claim', source_listing_id=EXCLUDED.source_listing_id,
       consented_at=NOW(), confirmation_token_hash=EXCLUDED.confirmation_token_hash,
       confirmation_expires_at=EXCLUDED.confirmation_expires_at,
       confirmation_sent_at=NULL, confirmation_send_reserved_at=NOW(),
       confirmed_at=NULL, unsubscribed_at=NULL, last_synced_at=NOW(), updated_at=NOW()
     WHERE toolindex_newsletter_contacts.status <> 'confirmed'
       AND (
         toolindex_newsletter_contacts.status='unsubscribed'
         OR toolindex_newsletter_contacts.confirmation_expires_at <= NOW()
         OR (
           toolindex_newsletter_contacts.status='pending'
           AND toolindex_newsletter_contacts.confirmation_sent_at IS NULL
           AND (
             toolindex_newsletter_contacts.confirmation_send_reserved_at IS NULL
             OR toolindex_newsletter_contacts.confirmation_send_reserved_at < NOW() - INTERVAL '15 minutes'
           )
         )
       )
     RETURNING status`,
    [norm, listingId || null, tokenHash]
  );
  if (!reservation.rows.length) {
    const current = await pool.query(
      `SELECT status FROM toolindex_newsletter_contacts WHERE email=$1 LIMIT 1`,
      [norm]
    );
    return current.rows[0]?.status === 'confirmed'
      ? { confirmed: true }
      : { pending: true, skipped: 'confirmation_in_progress' };
  }

  const baseUrl = process.env.APP_URL || 'https://strategic-flow-audit.replit.app';
  const confirmUrl = `${baseUrl}/newsletter/confirm?token=${encodeURIComponent(token)}`;
  const hookHtml = hookPost
    ? `<div style="border-left:3px solid #00d4c8;padding:12px 16px;margin:0 0 22px;background:#0b1b2d;">
         <p style="font-size:11px;color:#00d4c8;margin:0 0 6px;font-family:monospace;text-transform:uppercase;letter-spacing:.08em;">From today&rsquo;s ToolIndex article</p>
         <p style="font-size:14px;color:#cbd5e1;line-height:1.6;margin:0 0 10px;">${hookPost.excerpt}</p>
         <a href="${baseUrl}/blog/${encodeURIComponent(hookPost.slug)}" style="font-size:12px;color:#67e8f9;text-decoration:underline;">Read the full article →</a>
       </div>`
    : '';
  const hookText = hookPost
    ? `\n\nFrom today's ToolIndex article:\n${hookPost.excerpt}\nRead the full article: ${baseUrl}/blog/${hookPost.slug}\n`
    : '';
  try {
    const sendResult = await resend.emails.send({
      _skipGlobalCooldown: true,
      from: SENDER,
      replyTo: 'strategicflow@proton.me',
      to: norm,
      subject: 'Confirm your ToolIndex founder updates',
      html: `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:520px;margin:32px auto;background:#060e1c;color:#e2e8f0;padding:36px 32px;border-radius:14px;line-height:1.7;">
        <div style="font-family:monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#00d4c8;margin-bottom:20px;">ToolIndex · Founder updates</div>
        <h2 style="font-size:22px;color:#fff;margin:0 0 12px;">Confirm your subscription</h2>
         <p style="font-size:15px;color:#94a3b8;margin:0 0 22px;">You verified ownership of a product on ToolIndex. If you would like founder updates and new articles on Mondays, Wednesdays, and Fridays, confirm below to join the list.</p>
         ${hookHtml}
        <a href="${confirmUrl}" style="display:inline-block;background:#00d4c8;color:#041214;font-weight:700;font-size:13px;padding:12px 24px;border-radius:8px;text-decoration:none;font-family:monospace;">Confirm founder updates →</a>
        <p style="font-size:11px;color:#4a6a8a;margin-top:26px;">This link expires in 7 days. If you did not request these updates, ignore this email and you will not be subscribed.</p>
      </div>`,
        text: `You verified ownership of a product on ToolIndex. If you would like founder updates and new articles, confirm here:\n${confirmUrl}\n\nYou will receive updates on Mondays, Wednesdays, and Fridays. If you did not request this, ignore this email.${hookText}`,
    });
    if (sendResult?.cooldownBlocked) throw new Error('confirmation_cooldown_blocked');
    if (sendResult?.error) throw new Error(sendResult.error.message || 'Resend rejected confirmation email');
    await pool.query(
      `UPDATE toolindex_newsletter_contacts
       SET confirmation_sent_at=NOW(), confirmation_send_reserved_at=NULL, updated_at=NOW()
       WHERE email=$1 AND confirmation_token_hash=$2`,
      [norm, tokenHash]
    );
    return { confirmationSent: true };
  } catch (e) {
    await pool.query(
      `UPDATE toolindex_newsletter_contacts
       SET confirmation_send_reserved_at=NULL, updated_at=NOW()
       WHERE email=$1 AND confirmation_token_hash=$2`,
      [norm, tokenHash]
    ).catch(()=>{});
    console.error(`[newsletter-consent] confirmation send failed → ${norm}:`, e.message);
    return { error: 'confirmation_send_failed' };
  }
}

async function syncClaimedFounderNewsletterContacts({ includeAllVerified = false, includeAllClaimed = false, hookPost = null } = {}) {
  const allClaimedQuery = `
    SELECT DISTINCT ON (lower(trim(dl.claimed_by)))
      dl.id AS listing_id, lower(trim(dl.claimed_by)) AS email, dl.name
    FROM directory_listings dl
    WHERE dl.status='active' AND dl.claimed_by IS NOT NULL
      AND length(trim(dl.claimed_by)) > 3
    ORDER BY lower(trim(dl.claimed_by)), dl.claimed_at DESC NULLS LAST, dl.id DESC
  `;
  const verifiedClaimsQuery = `
    SELECT DISTINCT ON (lower(trim(dc.owner_email)))
      dc.listing_id, lower(trim(dc.owner_email)) AS email, dl.name
    FROM dir_claims dc
    JOIN directory_listings dl ON dl.id=dc.listing_id
    WHERE ($1::boolean OR dc.newsletter_opt_in=TRUE)
      AND dc.is_verified=TRUE
      AND dl.claimed_by IS NOT NULL
      AND lower(trim(dl.claimed_by))=lower(trim(dc.owner_email))
      AND dl.status='active'
    ORDER BY lower(trim(dc.owner_email)), dl.claimed_at DESC NULLS LAST, dc.listing_id DESC
  `;
  const { rows } = includeAllClaimed
    ? await pool.query(allClaimedQuery)
    : await pool.query(verifiedClaimsQuery, [includeAllVerified]);
  let confirmed = 0, pending = 0, skipped = 0, errors = 0;
  for (const row of rows) {
    try {
      if (BYPASS_EMAILS.has(row.email) || isJunkEmail(row.email)) {
        skipped++;
        continue;
      }
      const blocked = isBlockedOutreachTarget(row.name, row.email);
      if (blocked.blocked || await isUnsubscribed(row.email)) {
        skipped++;
        continue;
      }
      const result = await queueClaimNewsletterConfirmation(row.email, row.listing_id, { hookPost });
      if (result.confirmed) confirmed++;
      else if (result.confirmationSent || result.pending) pending++;
      else skipped++;
    } catch (e) {
      errors++;
      console.error(`[newsletter-sync] ${row.email}:`, e.message);
    }
    await new Promise(resolve => setTimeout(resolve, 120));
  }
  const scope = includeAllClaimed ? 'all active claimed owners' : includeAllVerified ? 'all verified claims' : 'opted-in claims';
  console.log(`[newsletter-sync] ${rows.length} ${scope} → ${confirmed} confirmed, ${pending} pending, ${skipped} skipped, ${errors} errors`);
  return { total: rows.length, confirmed, pending, skipped, errors, scope };
}

function buildUnsubFooterHtml(email) {
  return `<p style="font-size:11px;color:#9ca3af;margin-top:8px;">Don&rsquo;t want to hear from us? <a href="${unsubLink(email)}" style="color:#9ca3af;text-decoration:underline;">Unsubscribe</a> from all ToolIndex emails.</p>`;
}

// ── Centralized stop-on-engagement gate — shared by every automated sequence ──
// Checks unsubscribes + explicit engagement signals recorded via /admin/engage.
// Call this BEFORE every scheduled send. Returns { halted, reason }.
// Logs to sequence_halted_log whenever a send is prevented.
async function isSequenceHalted(email, seqName) {
  const norm = (email || '').toLowerCase().trim();
  if (!norm) return { halted: false };

  // 1. Global unsubscribe (highest priority)
  if (await isUnsubscribed(norm)) {
    await logSequenceHalt(norm, seqName, 'unsubscribed');
    return { halted: true, reason: 'unsubscribed' };
  }

  // 2. Explicit engagement record — either for this sequence or global (seq_name IS NULL)
  try {
    const { rows } = await pool.query(
      `SELECT reason FROM sequence_engagement
       WHERE lower(email) = $1 AND (seq_name IS NULL OR seq_name = $2)
       ORDER BY engaged_at DESC LIMIT 1`,
      [norm, seqName]
    );
    if (rows.length) {
      await logSequenceHalt(norm, seqName, rows[0].reason);
      return { halted: true, reason: rows[0].reason };
    }
  } catch { /* table may not exist yet on first deploy — non-fatal */ }

  return { halted: false };
}

async function logSequenceHalt(email, seqName, reason) {
  try {
    await pool.query(
      `INSERT INTO sequence_halted_log (email, seq_name, reason) VALUES ($1, $2, $3)`,
      [email, seqName, reason]
    );
    console.log(`[seq-halt] ${seqName || 'all'} → ${email} (${reason})`);
  } catch { /* non-fatal */ }
}
function buildUnsubFooterText(email) {
  return `\n\nTo unsubscribe from all emails: ${unsubLink(email)}`;
}

function buildSeqEmail(contact, stepNum) {
  // Step 3: use A/B paid-offer variant if assigned, fall back to cluster template
  let tpl;
  if (stepNum === 3 && contact.ab_variant && SEQ_STEP3_AB[contact.ab_variant]) {
    tpl = SEQ_STEP3_AB[contact.ab_variant];
  } else {
    tpl = SEQ_TEMPLATES[contact.cluster]?.[stepNum];
  }
  if (!tpl) throw new Error(`No template: cluster=${contact.cluster} step=${stepNum} variant=${contact.ab_variant}`);
  const merge = s => s
    .replace(/\{\{first_name\}\}/g, contact.first_name || 'there')
    .replace(/\{\{company\}\}/g,   contact.company    || 'your company');
  const bodyText = merge(tpl.body);
  // Variant A: render the URL line as a proper CTA button
  const bodyHtml = bodyText.split('\n\n').map(p => {
    const urlMatch = p.match(/^https?:\/\/\S+$/);
    if (urlMatch) {
      return `<p style="margin:0 0 18px;"><a href="${p.trim()}" style="display:inline-block;background:#00d4c8;color:#ffffff;font-family:Georgia,serif;font-size:14px;font-weight:bold;padding:12px 24px;border-radius:6px;text-decoration:none;">Decision Friction Review →</a></p>`;
    }
    return `<p style="margin:0 0 14px;font-size:14px;color:#374151;line-height:1.65;">${p.replace(/\n/g, '<br>')}</p>`;
  }).join('');
  const email = contact.to_email || '';
  return {
    subject: tpl.subject,
    html:    `<div style="font-family:Georgia,serif;max-width:580px;margin:auto;padding:32px 24px;color:#1f2937;background:#ffffff;">${bodyHtml}${SEQ_SIG_HTML}${buildUnsubFooterHtml(email)}</div>`,
    text:    bodyText + SEQ_SIG_TEXT + buildUnsubFooterText(email),
  };
}

// CSV parser (no external library needed)
function parseCsvLine(line) {
  const result = []; let cur = ''; let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { if (inQ && line[i+1] === '"') { cur += '"'; i++; } else inQ = !inQ; }
    else if (ch === ',' && !inQ) { result.push(cur); cur = ''; }
    else cur += ch;
  }
  result.push(cur);
  return result;
}
function parseSeqCsv(csvText) {
  const lines = csvText.replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n');
  if (!lines.length) return [];
  const hdr = parseCsvLine(lines[0]).map(h => h.trim().toLowerCase().replace(/[^a-z0-9_]/g,''));
  const col = k => hdr.findIndex(h => h === k);
  const eIdx = col('to_email'); const cIdx = col('cluster');
  if (eIdx < 0 || cIdx < 0) throw new Error('CSV must have columns: to_email, cluster');
  const fnIdx = col('first_name'); const coIdx = col('company'); const tIdx = col('title');
  const avIdx = col('ab_variant'); const s1Idx = col('step1_sent_at'); const s2Idx = col('step2_sent_at');
  const ssIdx = col('stop_sequence'); const impIdx = col('imported_at');
  const VALID = new Set(['A_PMM','B_Lifecycle','C_EmailMgr']);
  const VALID_AB = new Set(['A', 'B']);
  const seen = new Map();
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim(); if (!line) continue;
    const cols = parseCsvLine(line);
    const email = (cols[eIdx]||'').trim().toLowerCase();
    if (!email || !email.includes('@') || seen.has(email)) continue;
    const cluster = (cols[cIdx]||'').trim();
    if (!VALID.has(cluster)) continue;
    const abVariant = avIdx >= 0 ? (cols[avIdx]||'').trim() : '';
    const stopSequence = ssIdx >= 0
      ? ['true', '1', 'yes'].includes((cols[ssIdx]||'').trim().toLowerCase())
      : false;
    seen.set(email, {
      to_email:   email,
      first_name: fnIdx >= 0 ? (cols[fnIdx]||'').trim() : '',
      company:    coIdx >= 0 ? (cols[coIdx]||'').trim() : '',
      title:      tIdx  >= 0 ? (cols[tIdx] ||'').trim() : '',
      cluster,
      ab_variant: VALID_AB.has(abVariant) ? abVariant : null,
      step1_sent_at: s1Idx >= 0 ? (cols[s1Idx]||'').trim() || null : null,
      step2_sent_at: s2Idx >= 0 ? (cols[s2Idx]||'').trim() || null : null,
      stop_sequence: stopSequence,
      imported_at: impIdx >= 0 ? (cols[impIdx]||'').trim() || null : null,
    });
  }
  return [...seen.values()];
}

function isLifecycleOutreachPaused() {
  return String(process.env.LIFECYCLE_OUTREACH_PAUSED || '').toLowerCase() === 'true';
}

// Core batch runner — returns {sent, errors, log[]}
async function runSeqOutreachBatch(cap = OUTREACH_DAILY_CAP, options = {}) {
  if (!options.ignoreLifecyclePause && isLifecycleOutreachPaused()) {
    console.log('[seq-outreach] PAUSED — LIFECYCLE_OUTREACH_PAUSED=true');
    return { sent: 0, errors: 0, total: 0, log: ['paused'] };
  }
  // Legacy per-sequence pause gate remains supported.
  try {
    const { rows } = await pool.query(`SELECT value FROM system_config WHERE key='seq_outreach_paused' LIMIT 1`);
    if (rows[0]?.value === 'true') {
      console.log('[seq-outreach] PAUSED — seq_outreach_paused=true in system_config');
      return { sent: 0, errors: 0, total: 0, log: ['paused'] };
    }
  } catch { /* non-fatal — if table missing, continue */ }
  const r = await pool.query(`
    SELECT id, to_email, first_name, company, cluster, ab_variant, step, priority_at FROM (
      SELECT id, to_email, first_name, company, cluster, ab_variant, 1 AS step, imported_at AS priority_at
      FROM outreach_seq_contacts
      WHERE stop_sequence = false AND step1_sent_at IS NULL
      UNION ALL
      SELECT id, to_email, first_name, company, cluster, ab_variant, 2, step1_sent_at
      FROM outreach_seq_contacts
      WHERE stop_sequence = false AND step1_sent_at IS NOT NULL
        AND step2_sent_at IS NULL AND step1_sent_at <= NOW() - INTERVAL '4 days'
      UNION ALL
      SELECT id, to_email, first_name, company, cluster, ab_variant, 3, step2_sent_at
      FROM outreach_seq_contacts
      WHERE stop_sequence = false AND step2_sent_at IS NOT NULL
        AND step3_sent_at IS NULL AND step2_sent_at <= NOW() - INTERVAL '5 days'
    ) q ORDER BY step ASC, priority_at ASC LIMIT $1`, [cap]);
  let sent = 0, errors = 0; const log = [];
  for (const contact of r.rows) {
    if (await isUnsubscribed(contact.to_email)) {
      await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=true WHERE id=$1`, [contact.id]);
      log.push(`⊘ unsubscribed → ${contact.to_email}`); continue;
    }
    const seqBlock = isBlockedOutreachTarget(contact.company, contact.to_email);
    if (seqBlock.blocked) {
      await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=true WHERE id=$1`, [contact.id]);
      log.push(`⊘ blocked (${seqBlock.reason}) → ${contact.to_email}`); continue;
    }
    // Engagement stop — halts if recipient replied or took a meaningful action
    const engCheck = await isSequenceHalted(contact.to_email, 'agency_outreach');
    if (engCheck.halted) {
      await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=true, engaged_at=NOW(), engaged_reason=$2 WHERE id=$1`, [contact.id, engCheck.reason]);
      log.push(`⊘ engagement-halted (${engCheck.reason}) → ${contact.to_email}`); continue;
    }
    try {
      const { subject, html, text } = buildSeqEmail(contact, contact.step);
      await resend.emails.send({ from: SENDER, to: contact.to_email, replyTo: 'strategicflow@proton.me', subject, html, text });
      const col = `step${contact.step}_sent_at`;
      await pool.query(`UPDATE outreach_seq_contacts SET ${col}=NOW() WHERE id=$1`, [contact.id]);
      log.push(`✓ step${contact.step} → ${contact.to_email}`); sent++;
    } catch(e) {
      const col = `step${contact.step}_error`;
      await pool.query(`UPDATE outreach_seq_contacts SET ${col}=$1 WHERE id=$2`, [e.message.slice(0,500), contact.id]).catch(()=>{});
      log.push(`✗ step${contact.step} → ${contact.to_email}: ${e.message}`); errors++;
    }
    await new Promise(res => setTimeout(res, 120)); // pace sends
  }
  return { sent, errors, total: r.rows.length, log };
}

// Strict Campaign 3 Step 3 runner.
// This runner intentionally has no lifecycle-pause bypass and cannot select
// Step 1 or Step 2 contacts.
let strictStep3BatchInFlight = false;

async function runStrictStep3Batch(cap = 100) {
  const batchCap = Math.min(
    Math.max(Number.parseInt(String(cap), 10) || 100, 1),
    100
  );

  if (strictStep3BatchInFlight) {
    return {
      sent: 0,
      errors: 0,
      skipped: 0,
      total: 0,
      in_flight: true,
      log: ['strict_step3_batch_already_running'],
    };
  }

  if (isLifecycleOutreachPaused()) {
    console.log('[seq-step3-strict] PAUSED — LIFECYCLE_OUTREACH_PAUSED=true');
    return {
      sent: 0,
      errors: 0,
      skipped: 0,
      total: 0,
      paused: true,
      log: ['lifecycle_outreach_paused'],
    };
  }

  strictStep3BatchInFlight = true;
  try {
    try {
      const { rows: pauseRows } = await pool.query(
        `SELECT value
         FROM system_config
         WHERE key='seq_outreach_paused'
         LIMIT 1`
      );
      if (pauseRows[0]?.value === 'true') {
        console.log('[seq-step3-strict] PAUSED — seq_outreach_paused=true');
        return {
          sent: 0,
          errors: 0,
          skipped: 0,
          total: 0,
          paused: true,
          log: ['seq_outreach_paused'],
        };
      }
    } catch (e) {
      console.error('[seq-step3-strict] pause check failed:', e.message);
      return {
        sent: 0,
        errors: 0,
        skipped: 0,
        total: 0,
        paused: true,
        pause_check_error: true,
        log: ['system_config_pause_check_failed'],
      };
    }

    const { rows } = await pool.query(
      `SELECT
         osc.id,
         osc.to_email,
         osc.first_name,
         osc.company,
         osc.cluster,
         osc.ab_variant
       FROM outreach_seq_contacts osc
       WHERE osc.stop_sequence = false
         AND osc.step2_sent_at IS NOT NULL
         AND osc.step3_sent_at IS NULL
         AND osc.step2_sent_at <= NOW() - INTERVAL '5 days'
         AND NOT EXISTS (
           SELECT 1
           FROM email_unsubscribes eu
           WHERE lower(trim(eu.email)) = lower(trim(osc.to_email))
         )
       ORDER BY osc.step2_sent_at ASC, osc.imported_at ASC
       LIMIT $1`,
      [batchCap]
    );

    let sent = 0;
    let errors = 0;
    let skipped = 0;
    const log = [];

    for (const contact of rows) {
      if (await isUnsubscribed(contact.to_email)) {
        await pool.query(
          `UPDATE outreach_seq_contacts
           SET stop_sequence = true
           WHERE id = $1`,
          [contact.id]
        );
        skipped++;
        log.push(`unsubscribed → ${contact.to_email}`);
        continue;
      }

      const blocked = isBlockedOutreachTarget(
        contact.company,
        contact.to_email
      );
      if (blocked.blocked) {
        await pool.query(
          `UPDATE outreach_seq_contacts
           SET stop_sequence = true
           WHERE id = $1`,
          [contact.id]
        );
        skipped++;
        log.push(`blocked (${blocked.reason}) → ${contact.to_email}`);
        continue;
      }

      const halted = await isSequenceHalted(
        contact.to_email,
        'agency_outreach'
      );
      if (halted.halted) {
        await pool.query(
          `UPDATE outreach_seq_contacts
           SET stop_sequence = true,
               engaged_at = NOW(),
               engaged_reason = $2
           WHERE id = $1`,
          [contact.id, halted.reason]
        );
        skipped++;
        log.push(`engagement-halted (${halted.reason}) → ${contact.to_email}`);
        continue;
      }

      try {
        const { subject, html, text } = buildSeqEmail(contact, 3);
        await resend.emails.send({
          from: SENDER,
          to: contact.to_email,
          replyTo: 'strategicflow@proton.me',
          subject,
          html,
          text,
        });
        await pool.query(
          `UPDATE outreach_seq_contacts
           SET step3_sent_at = NOW()
           WHERE id = $1`,
          [contact.id]
        );
        sent++;
        log.push(`step3 → ${contact.to_email}`);
      } catch (e) {
        await pool.query(
          `UPDATE outreach_seq_contacts
           SET step3_error = $1
           WHERE id = $2`,
          [e.message.slice(0, 500), contact.id]
        ).catch(() => {});
        errors++;
        log.push(`step3 error → ${contact.to_email}: ${e.message}`);
      }

      await new Promise(resolve => setTimeout(resolve, 120));
    }

    return { sent, errors, skipped, total: rows.length, log };
  } finally {
    strictStep3BatchInFlight = false;
  }
}

// Multer instance for CSV uploads
const csvUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });

// ── GET /admin/seq-outreach?key=… — admin dashboard page ─────────────────────
app.get('/admin/seq-outreach', (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).send('Forbidden');
  res.sendFile(path.join(__dirname, 'public', 'admin-seq-outreach.html'));
});

// ── POST /admin/seq-upload-csv?key=… — import contacts from CSV ───────────────
app.post('/admin/seq-upload-csv', csvUpload.single('csv'), async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  try {
    const contacts = parseSeqCsv(req.file.buffer.toString('utf8'));
    if (!contacts.length) return res.status(400).json({ error: 'No valid contacts found in CSV' });
    let imported = 0, updated = 0, skipped = 0;
    for (const c of contacts) {
      const r = await pool.query(
        `INSERT INTO outreach_seq_contacts
           (to_email, first_name, company, title, cluster, ab_variant,
            step1_sent_at, step2_sent_at, stop_sequence, imported_at)
         VALUES ($1,$2,$3,$4,$5,$6,NULLIF($7,'')::timestamptz,NULLIF($8,'')::timestamptz,$9,
                 COALESCE(NULLIF($10,'')::timestamptz,NOW()))
         ON CONFLICT (to_email) DO UPDATE SET
           first_name=EXCLUDED.first_name,
           company=EXCLUDED.company,
           title=EXCLUDED.title,
           cluster=EXCLUDED.cluster,
           ab_variant=EXCLUDED.ab_variant,
           step1_sent_at=EXCLUDED.step1_sent_at,
           step2_sent_at=EXCLUDED.step2_sent_at,
           stop_sequence=EXCLUDED.stop_sequence,
           imported_at=EXCLUDED.imported_at`,
        [
          c.to_email, c.first_name, c.company, c.title, c.cluster, c.ab_variant,
          c.step1_sent_at || '', c.step2_sent_at || '', c.stop_sequence, c.imported_at || ''
        ]
      );
      if (r.command === 'INSERT') imported++; else if (r.command === 'UPDATE') updated++; else skipped++;
    }
    console.log(`[seq-outreach] CSV import: ${imported} imported, ${updated} updated, ${skipped} skipped`);
    res.json({ ok: true, imported, updated, skipped, total_in_file: contacts.length });
  } catch(e) {
    res.status(400).json({ error: e.message });
  }
});

// ── GET /admin/seq-stats?key=… — campaign statistics ─────────────────────────
app.get('/admin/seq-stats', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  try {
    const { rows } = await pool.query(`
      SELECT
        COUNT(*)                                          AS total,
        COUNT(*) FILTER (WHERE stop_sequence)            AS stopped,
        COUNT(*) FILTER (WHERE step1_sent_at IS NOT NULL) AS step1_done,
        COUNT(*) FILTER (WHERE step2_sent_at IS NOT NULL) AS step2_done,
        COUNT(*) FILTER (WHERE step3_sent_at IS NOT NULL) AS step3_done,
        COUNT(*) FILTER (WHERE step1_sent_at IS NULL AND NOT stop_sequence) AS step1_pending,
        COUNT(*) FILTER (WHERE step1_sent_at IS NOT NULL AND step2_sent_at IS NULL AND NOT stop_sequence
                          AND step1_sent_at <= NOW()-INTERVAL '4 days') AS step2_ready,
        COUNT(*) FILTER (WHERE step2_sent_at IS NOT NULL AND step3_sent_at IS NULL AND NOT stop_sequence
                          AND step1_sent_at <= NOW()-INTERVAL '8 days') AS step3_ready,
        COUNT(*) FILTER (WHERE cluster='A_PMM')          AS cluster_a,
        COUNT(*) FILTER (WHERE cluster='B_Lifecycle')     AS cluster_b,
        COUNT(*) FILTER (WHERE cluster='C_EmailMgr')      AS cluster_c
      FROM outreach_seq_contacts`);
    res.json({ ok: true, stats: rows[0], daily_cap: OUTREACH_DAILY_CAP });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── GET /admin/seq-contacts?key=…&page=N&q=…&cluster=… — paginated list ──────
app.get('/admin/seq-contacts', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const page = Math.max(1, parseInt(req.query.page || '1', 10));
  const limit = 50; const offset = (page - 1) * limit;
  const q = req.query.q ? `%${req.query.q}%` : null;
  const cluster = req.query.cluster || null;
  try {
    const params = [limit, offset];
    let where = 'WHERE 1=1';
    if (q)       { params.push(q); where += ` AND (to_email ILIKE $${params.length} OR first_name ILIKE $${params.length} OR company ILIKE $${params.length})`; }
    if (cluster) { params.push(cluster); where += ` AND cluster=$${params.length}`; }
    const { rows } = await pool.query(
      `SELECT id, to_email, first_name, company, title, cluster,
              step1_sent_at, step2_sent_at, step3_sent_at,
              step1_error, step2_error, step3_error,
              stop_sequence, imported_at
       FROM outreach_seq_contacts ${where}
       ORDER BY imported_at DESC LIMIT $1 OFFSET $2`, params);
    const tot = await pool.query(`SELECT COUNT(*) FROM outreach_seq_contacts ${where}`,
      params.slice(2));
    res.json({ ok: true, contacts: rows, total: parseInt(tot.rows[0].count, 10), page, limit });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── POST /admin/engage?key=… — mark an email as engaged (replied / acted) ──────
// Halts ALL automated sequences for that email unless seq_name scopes it.
// Body: { email, reason = "replied", seq_name? }  (seq_name null = halt everywhere)
app.post('/admin/engage', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const { email, reason = 'replied', seq_name } = req.body || {};
  if (!email?.includes('@')) return res.status(400).json({ error: 'email_required' });
  const norm = email.toLowerCase().trim();
  try {
    // Record in sequence_engagement (upsert)
    await pool.query(
      `INSERT INTO sequence_engagement (email, seq_name, reason)
       VALUES ($1, $2, $3)
       ON CONFLICT (lower(email), coalesce(seq_name,''))
       DO UPDATE SET reason = EXCLUDED.reason, engaged_at = NOW()`,
      [norm, seq_name || null, reason]
    );
    // Also set stop_sequence on any outreach_seq_contacts row (agency outreach)
    const { rowCount } = await pool.query(
      `UPDATE outreach_seq_contacts
       SET stop_sequence = true, engaged_at = NOW(), engaged_reason = $2
       WHERE lower(to_email) = $1 AND stop_sequence = false`,
      [norm, reason]
    );
    console.log(`[admin/engage] ${norm} marked as engaged (${reason}) — scope: ${seq_name || 'all'}, agency rows updated: ${rowCount}`);
    res.json({ ok: true, email: norm, reason, seq_name: seq_name || null, agency_rows_stopped: rowCount });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// ── POST /admin/seq-stop-contact?key=…&id=…&stop=0|1 — toggle stop ───────────
app.post('/admin/seq-stop-contact', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const id = parseInt(req.query.id || req.body?.id, 10);
  const stop = (req.query.stop ?? req.body?.stop) !== '0';
  if (!id) return res.status(400).json({ error: 'missing id' });
  await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=$1 WHERE id=$2`, [stop, id]);
  res.json({ ok: true, id, stop_sequence: stop });
});

// ── POST /admin/seq-run-batch?key=…&cap=N — manually trigger a batch ─────────
app.post('/admin/seq-run-batch', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const cap = Math.min(parseInt(req.query.cap || String(OUTREACH_DAILY_CAP), 10), 100);
  res.setHeader('Content-Type', 'application/json');
  try {
    const result = await runSeqOutreachBatch(cap);
    console.log(`[seq-outreach] manual batch: ${result.sent} sent, ${result.errors} errors`);
    res.json({ ok: true, ...result });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── POST /admin/seq-send-step3-strict?key=…&cap=N ─────────────────────────────
// The only manual endpoint for strict Campaign 3 Step 3 sends.
app.post('/admin/seq-send-step3-strict', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const cap = Math.min(
    Math.max(Number.parseInt(req.query.cap || '100', 10) || 100, 1),
    100
  );

  res.setHeader('Content-Type', 'application/json');
  try {
    const result = await runStrictStep3Batch(cap);
    if (result.paused) {
      return res.status(423).json({
        ok: false,
        runner: 'strict_step3',
        ...result,
      });
    }
    if (result.in_flight) {
      return res.status(409).json({
        ok: false,
        runner: 'strict_step3',
        ...result,
      });
    }
    console.log(
      `[seq-step3-strict] ${result.sent} sent, ` +
      `${result.errors} errors, ${result.skipped} skipped ` +
      `out of ${result.total} queued`
    );
    res.json({
      ok: true,
      runner: 'strict_step3',
      cap,
      ...result,
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── POST /admin/seq-send-step3-ab?key=…&cap=N&dry_run=1 — send A/B step 3 final email ──
// Sends to contacts who got step1 but NOT step3 yet (bypasses step2 requirement by design).
// dry_run=1 returns the queue without sending anything.
app.post('/admin/seq-send-step3-ab', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const cap     = Math.min(parseInt(req.query.cap || '300', 10), 600);
  const dryRun  = req.query.dry_run === '1';
  if (!dryRun && isLifecycleOutreachPaused()) return res.status(423).json({ error: 'outreach_paused', message: 'Lifecycle outreach is paused.' });
  res.setHeader('Content-Type', 'application/json');
  try {
    const { rows } = await pool.query(`
      SELECT id, to_email, first_name, company, cluster, ab_variant
      FROM outreach_seq_contacts
      WHERE stop_sequence = false
        AND step1_sent_at IS NOT NULL
        AND step3_sent_at IS NULL
        AND ab_variant IS NOT NULL
      ORDER BY imported_at
      LIMIT $1`, [cap]);
    if (dryRun) return res.json({ dry_run: true, total: rows.length, a: rows.filter(r=>r.ab_variant==='A').length, b: rows.filter(r=>r.ab_variant==='B').length, sample: rows.slice(0,3) });
    let sent = 0, errors = 0; const log = [];
    for (const contact of rows) {
      if (await isUnsubscribed(contact.to_email)) {
        await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=true WHERE id=$1`, [contact.id]);
        log.push(`⊘ unsub → ${contact.to_email}`); continue;
      }
      const engCheck = await isSequenceHalted(contact.to_email, 'agency_outreach');
      if (engCheck.halted) {
        await pool.query(`UPDATE outreach_seq_contacts SET stop_sequence=true, engaged_at=NOW(), engaged_reason=$2 WHERE id=$1`, [contact.id, engCheck.reason]);
        log.push(`⊘ halted (${engCheck.reason}) → ${contact.to_email}`); continue;
      }
      try {
        const { subject, html, text } = buildSeqEmail(contact, 3);
        await resend.emails.send({ from: SENDER, to: contact.to_email, replyTo: 'strategicflow@proton.me', subject, html, text });
        await pool.query(`UPDATE outreach_seq_contacts SET step3_sent_at=NOW() WHERE id=$1`, [contact.id]);
        log.push(`✓ [${contact.ab_variant}] → ${contact.to_email}`); sent++;
      } catch(e) {
        await pool.query(`UPDATE outreach_seq_contacts SET step3_error=$1 WHERE id=$2`, [e.message.slice(0,500), contact.id]).catch(()=>{});
        log.push(`✗ [${contact.ab_variant}] → ${contact.to_email}: ${e.message}`); errors++;
      }
      await new Promise(r => setTimeout(r, 120));
    }
    console.log(`[seq-step3-ab] ${sent} sent (${rows.filter(r=>r.ab_variant==='A').length} A / ${rows.filter(r=>r.ab_variant==='B').length} B queued), ${errors} errors`);
    res.json({ ok: true, sent, errors, total: rows.length, log });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── GET /admin/seq-step3-ab-stats?key=… — A/B variant engagement breakdown ──
app.get('/admin/seq-step3-ab-stats', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  try {
    const { rows } = await pool.query(`
      SELECT
        ab_variant,
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE step3_sent_at IS NOT NULL) AS sent,
        COUNT(*) FILTER (WHERE step3_sent_at IS NULL AND stop_sequence = false) AS pending,
        COUNT(*) FILTER (WHERE engaged_at > step3_sent_at) AS engaged_after_step3,
        COUNT(*) FILTER (WHERE stop_sequence = true) AS stopped
      FROM outreach_seq_contacts
      WHERE ab_variant IS NOT NULL
      GROUP BY ab_variant ORDER BY ab_variant`);
    res.json({ ok: true, variants: rows });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

