// ── POST /admin/extract-contacts-deep?key=… — re-scan not_found listings with more pages ─
let _deepScanRunning = false;
app.post('/admin/extract-contacts-deep', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  if (_deepScanRunning) return res.json({ ok: false, message: 'already running' });
  _deepScanRunning = true;
  res.json({ ok: true, message: 'deep scan started in background' });

  setImmediate(async () => {
    const CONCURRENCY = 10;
    const EMAIL_RE = /\b([a-zA-Z0-9._%+\-]{1,40}@[a-zA-Z0-9.\-]{1,60}\.[a-zA-Z]{2,10})\b/g;
    const SKIP_L = /^(noreply|no-reply|donotreply|mailer-daemon|bounce|postmaster|unsubscribe|privacy@example|test|user|name|someone|your|admin|webmaster|info@example|hello@gmail|support@gmail|contact@gmail|you@|hello@email|hello@company|hello@lawfirm|footer_|logo@|gf-icn)/i;
    const SKIP_D = /example\.|test\.|placeholder\.|sentry\.|mailchimp\.com|sendgrid\.net|amazonaws\.com|wixpress\.com|squarespace\.com|gmail\.com$|yahoo\.com$|hotmail\.com$/i;
    const tf = (u) => safeFetchPublicUrl(u, { timeoutMs: 8000, maxBytes: 1024 * 1024, headers: { 'User-Agent': 'Mozilla/5.0 (compatible; ToolIndex/1.0)' } });
    const cl = h => h.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'');
    const getEmail = html => {
      const text = cl(html);
      const mt=[...text.matchAll(/href=["']mailto:([^"'?\s]{3,80})["']/gi)].map(m=>m[1].split('?')[0].toLowerCase().trim()).filter(e=>/^[^@]{1,40}@[^@]{1,60}\.[a-z]{2,10}$/.test(e)&&!SKIP_L.test(e)&&!SKIP_D.test(e));
      if(mt.length)return mt[0];
      for(const m of [...text.matchAll(/(?:contact\s+us|email\s+us|reach\s+us|get\s+in\s+touch|hello@|hi@|support@|team@|info@|press@|partner)[\s\S]{0,400}/gi)]){
        const em=[...m[0].matchAll(EMAIL_RE)].map(e=>e[1].toLowerCase()).filter(e=>!SKIP_L.test(e)&&!SKIP_D.test(e));
        if(em.length)return em[0];
      }
      const ft=text.match(/<footer[\s\S]{0,8000}/i)?.[0]||text.slice(-6000);
      return([...ft.matchAll(EMAIL_RE)].map(e=>e[1].toLowerCase()).filter(e=>!SKIP_L.test(e)&&!SKIP_D.test(e))[0])||null;
    };
    const getLI = html => { const m=[...html.matchAll(/https?:\/\/(?:www\.)?linkedin\.com\/(in|company)\/([a-zA-Z0-9_%-]{2,80})\/?/g)]; if(!m.length)return null; const p=m.find(x=>x[1]==='in')||m[0]; return`https://www.linkedin.com/${p[1]}/${p[2]}/`; };

    try {
      const { rows } = await pool.query(`SELECT id,name,url FROM directory_listings WHERE status='active' AND contact_email_status='not_found' ORDER BY id`);
      console.log(`[extract-deep] Starting deep scan for ${rows.length} not_found listings at concurrency ${CONCURRENCY}`);
      let done=0, found=0, li=0, i=0;
      const EXTRA_PAGES = ['/contact', '/about', '/team', '/help', '/support', '/company', '/legal/privacy', '/privacy-policy', '/imprint'];
      const worker = async () => {
        while(i<rows.length){
          const l=rows[i++];
          try{
            let base; try{base=new URL(l.url).origin;}catch{done++;continue;}
            let email=null,linkedin=null,src=null;
            const pages=[l.url,...EXTRA_PAGES.map(p=>`${base}${p}`)];
            for(const pg of pages){
              try{
                const r=await tf(pg); if(!r||!r.ok)continue;
                const html=await r.text().catch(()=>'');
                if(!email){email=getEmail(html);if(email)src=pg;}
                if(!linkedin)linkedin=getLI(html);
                if(email&&linkedin)break;
              }catch{}
            }
            const status=email?'found':'not_found';
            const liQ=linkedin?`,social_linkedin=COALESCE(NULLIF(social_linkedin,''),$5)`:'';
            await pool.query(`UPDATE directory_listings SET contact_email=$1,contact_email_status=$2,contact_email_source=$3,contact_email_fetched_at=NOW()${liQ} WHERE id=$4`,
              linkedin?[email||null,status,src||null,l.id,linkedin]:[email||null,status,src||null,l.id]);
            if(email){found++;console.log(`[extract-deep] ✓ ${l.name} → ${email}`);}
            if(linkedin)li++; done++;
            if(done%25===0)console.log(`[extract-deep] ${done}/${rows.length} — emails:${found} linkedin:${li}`);
          }catch(e){ done++; }
        }
      };
      await Promise.all(Array.from({length:CONCURRENCY},worker));
      console.log(`[extract-deep] DONE — found:${found} linkedin:${li} / ${rows.length} scanned`);
      // Auto-send claim outreach to newly discovered emails.
      if (found > 0) {
        try {
          const { rows: newLeads } = await pool.query(`
            SELECT id, name, contact_email, ai_insights FROM directory_listings
            WHERE contact_email_status='found' AND outreach_emailed_at IS NULL
              AND claimed_by IS NULL AND status='active' AND contact_email IS NOT NULL
            ORDER BY id ASC`);
          let autoSent = 0, autoSkipped = 0;
          for (const listing of newLeads) {
            if (isJunkEmail(listing.contact_email)) {
              await pool.query(`UPDATE directory_listings SET contact_email=NULL,contact_email_status='not_found' WHERE id=$1`, [listing.id]);
              autoSkipped++; continue;
            }
            const deepBlock = isBlockedOutreachTarget(listing.name, listing.contact_email);
            if (deepBlock.blocked) {
              await pool.query(`UPDATE directory_listings SET contact_email_status='excluded' WHERE id=$1`, [listing.id]);
              console.log(`[extract-deep] ⊘ blocked (${deepBlock.reason}) → ${listing.contact_email} (${listing.name})`);
              autoSkipped++; continue;
            }
            try {
              const slug = toListingSlug(listing.name, listing.id);
              const listingUrl = `https://strategic-flow-audit.replit.app/directory/${slug}`;
              const { subject, html: htmlBody, text: textBody } = buildClaimOutreachEmail(listing.name, listingUrl, listing.ai_insights);
              await resend.emails.send({ from: SENDER, to: listing.contact_email, replyTo: 'strategicflow@proton.me', subject, html: htmlBody, text: textBody });
              await pool.query(`UPDATE directory_listings SET outreach_emailed_at=NOW() WHERE id=$1`, [listing.id]);
              console.log(`[extract-deep] ✉ outreach → ${listing.contact_email} (${listing.name})`);
              autoSent++;
            } catch(e) { console.error(`[extract-deep] outreach error ${listing.contact_email}:`, e.message); }
            await new Promise(r => setTimeout(r, 300));
          }
          console.log(`[extract-deep] Auto-outreach: ${autoSent} sent, ${autoSkipped} junk skipped`);
        } catch(e) { console.error('[extract-deep] auto-outreach error:', e.message); }
      }
    } catch(e){ console.error('[extract-deep] FATAL:',e.message); }
    finally { _deepScanRunning = false; }
  });
});

// ── GET /admin/run-vote-growth?key=… — manually trigger daily vote growth cron ─
app.get('/admin/run-vote-growth', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.setHeader('Transfer-Encoding', 'chunked');
  res.flushHeaders();
  const log = m => { console.log(m); res.write(m + '\n'); };
  try {
    const dateTag = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    let grown = 0;

    // ── Promoted listings (is_promoted=TRUE): 10–14 votes/day, no cap ───────────
    const { rows: promoted } = await pool.query(
      `SELECT id, name, vote_count FROM directory_listings
       WHERE is_promoted = TRUE AND status = 'active'
         AND id <> ALL($1::int[])`,
      [Array.from(SEED_VOTE_DISABLED_IDS)]
    );
    for (const listing of promoted) {
      const toAdd = 10 + Math.floor(Math.random() * 5); // 10–14
      const voteRows = Array.from({ length: toAdd }, (_, i) =>
        `(${listing.id}, 'promoted_growth_${listing.id}_${dateTag}_${i}', NOW() - interval '${i * 90} minutes')`
      ).join(',');
      await pool.query(
        `INSERT INTO dir_votes (listing_id, voter_hash, voted_at) VALUES ${voteRows} ON CONFLICT DO NOTHING`
      );
      const r = await pool.query(
        `UPDATE directory_listings SET vote_count = vote_count + $1 WHERE id = $2 RETURNING vote_count`,
        [toAdd, listing.id]
      );
      log(`[vote-growth] PROMOTED +${toAdd} → ${listing.name} (now ${r.rows[0]?.vote_count})`);
      grown++;
    }
    const promotedIds = promoted.map(p => p.id);

    // Free/unclaimed listings do NOT get continued daily growth.
    // They receive their unique vote count once at seedDailySection time and stay there.
    log(`[vote-growth] Done. Grew ${grown} listings (${promoted.length} promoted — free listings frozen at seed counts).`);
  } catch (e) {
    log(`[vote-growth] ERROR: ${e.message}`);
  }
  res.end();
});

// ── GET /admin/enrich-listings?key=…&batch=20 — backfill AI insights ─────────
// Processes listings that have no ai_insights yet, oldest first, up to `batch` at a time.
app.get('/admin/enrich-listings', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const batchSize = Math.min(parseInt(req.query.batch || '10', 10), 30);

  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.setHeader('Transfer-Encoding', 'chunked');
  res.flushHeaders();
  const log = m => { console.log(m); res.write(m + '\n'); };

  try {
    const r = await pool.query(
      `SELECT id, name, url, category, COALESCE(owner_description, description) AS description
       FROM directory_listings
       WHERE status='active' AND ai_insights IS NULL
       ORDER BY submitted_at DESC
       LIMIT $1`,
      [batchSize]
    );
    log(`[enrich] Found ${r.rows.length} listings without AI insights (batch=${batchSize})`);

    let done = 0, failed = 0;
    for (const row of r.rows) {
      log(`[enrich] (${done + 1}/${r.rows.length}) ${row.name} — ${row.url}`);
      const result = await enrichListingWithAI(row, pool, claudeJSON);
      if (result) done++;
      else failed++;
      await new Promise(r => setTimeout(r, 2500)); // rate-limit Claude calls
    }

    log(`\n[enrich] Done. Enriched: ${done}  Failed: ${failed}`);
    // Invalidate cached count so the updated data shows immediately
    _cachedListingCountAt = 0;
  } catch (e) {
    log(`[enrich] ERROR: ${e.message}`);
  }
  res.end();
});

// ── GET /admin/backfill-logos?key=… — fetch real logos for Google-favicon-only listings ─────
let _backfillLogosRunning = false;
app.get('/admin/backfill-logos', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  if (_backfillLogosRunning) return res.json({ ok: false, message: 'Already running' });
  res.json({ ok: true, message: 'Logo backfill started in background — check server logs' });

  _backfillLogosRunning = true;
  (async () => {
    console.log('[backfill-logos] Starting Task #23 — backfill real logos');
    const HERO_PAT = [/og[-_]?image/i,/opengraph/i,/screenshot/i,/social[-_]?(?:preview|share)/i,/twitter[-_]?card/i,/banner/i,/\/hero[/_.]/i,/placeholder/i,/noimage/i];
    const CDN_SET = new Set(['s3.amazonaws.com','cloudfront.net','cloudinary.com','imgix.net','imagekit.io','res.cloudinary.com','cdn.shopify.com','logo.clearbit.com']);
    function validateLogo(url, domain) {
      if (!url) return false;
      if (HERO_PAT.some(re => re.test(url))) return false;
      try {
        const h = new URL(url).hostname.replace(/^www\./,'');
        if (h===domain||h.endsWith('.'+domain)||domain.endsWith('.'+h)) return true;
        if (h.split('.').slice(-2).join('.')===domain.split('.').slice(-2).join('.')) return true;
        for(const cdn of CDN_SET) if(h===cdn||h.endsWith('.'+cdn)) return true;
        return false;
      } catch { return false; }
    }
    async function timedFetch(u,ms=7000){return safeFetchPublicUrl(u,{timeoutMs:ms,maxBytes:1024*1024,headers:{'User-Agent':'Mozilla/5.0 (compatible; ToolIndex/1.0)'}});}
    async function getBetterLogo(siteUrl) {
      let base,domain;
      try{const p=new URL(siteUrl);base=p.origin;domain=p.hostname.replace(/^www\/./,'');}catch{return null;}
      try{const r=await timedFetch(`${base}/apple-touch-icon.png`,5000);if(r.ok&&r.headers.get('content-type')?.startsWith('image'))return`${base}/apple-touch-icon.png`;}catch{}
      try{
        const r=await timedFetch(siteUrl,8000);
        if(r.ok){
          const html=(await r.text()).slice(0,30000);
          const ogM=html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)||html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
          if(ogM){const c=new URL(ogM[1],base).href;if(validateLogo(c,domain))return c;}
          const re=/<link[^>]+rel=["'][^"']*icon[^"']*["'][^>]+href=["']([^"']+)["'][^>]*>/gi;let m;
          while((m=re.exec(html))!==null){const c=new URL(m[1],base).href;if(/\.(png|svg|webp)(\?|$)/i.test(c)&&!HERO_PAT.some(p=>p.test(c)))return c;}
        }
      }catch{}
      try{const r=await timedFetch(`${base}/favicon.ico`,5000);if(r.ok)return`${base}/favicon.ico`;}catch{}
      return`https://logo.clearbit.com/${domain}?size=128`;
    }
    try {
      const {rows} = await pool.query(`SELECT id,name,url FROM directory_listings WHERE status='active' AND (image_url IS NULL OR image_url='' OR image_url LIKE '%google.com/s2/favicons%') ORDER BY vote_count DESC,id`);
      console.log(`[backfill-logos] ${rows.length} listings to process`);
      let upgraded=0,failed=0;
      for(const row of rows){
        try{
          const logo=await getBetterLogo(row.url);
          if(logo){await pool.query('UPDATE directory_listings SET image_url=$1 WHERE id=$2',[logo,row.id]);upgraded++;}
          else failed++;
          console.log(`[backfill-logos] ${row.name}(${row.id}) → ${logo||'none'}`);
        }catch(e){failed++;console.error(`[backfill-logos] ${row.id} err:`,e.message);}
        await new Promise(r=>setTimeout(r,2000));
      }
      console.log(`[backfill-logos] Done. upgraded=${upgraded} failed=${failed}`);
    } catch(e) { console.error('[backfill-logos] fatal:', e.message); }
    _backfillLogosRunning = false;
  })();
});

// ── GET /admin/recategorize-other?key=… — re-classify "Other" listings via Claude ────────
let _recategorizeRunning = false;
const _VALID_CATS = ['AI Tools','Developer Tools','Design','Productivity','Marketing','Social Media','Analytics','Finance','Sales','Education','No-Code','Directories','HR & Recruiting','General'];
app.get('/admin/recategorize-other', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  if (_recategorizeRunning) return res.json({ ok: false, message: 'Already running' });
  res.json({ ok: true, message: 'Recategorize started in background — check server logs' });

  _recategorizeRunning = true;
  (async () => {
    console.log('[recategorize] Starting Task #114 — re-classify Other listings');
    try {
      const {rows} = await pool.query(`SELECT id,name,url,description FROM directory_listings WHERE status='active' AND category='Other' ORDER BY vote_count DESC,id`);
      console.log(`[recategorize] ${rows.length} listings to classify`);
      const stats={};
      for(const row of rows){
        try{
          const prompt=`Classify this SaaS product into one of these categories:\n${_VALID_CATS.join(', ')}\n\nProduct: ${row.name}\nURL: ${row.url}\nDescription: ${(row.description||'').slice(0,300)}\n\nReply with ONLY the category name, nothing else.`;
          const msg=await claude.messages.create({model:'claude-haiku-4-5',max_tokens:20,messages:[{role:'user',content:prompt}]});
          const cat=(msg.content[0]?.text||'').trim().replace(/['"]/g,'');
          const finalCat=_VALID_CATS.includes(cat)?cat:'General';
          await pool.query('UPDATE directory_listings SET category=$1 WHERE id=$2',[finalCat,row.id]);
          stats[finalCat]=(stats[finalCat]||0)+1;
          console.log(`[recategorize] ${row.name}(${row.id}) → ${finalCat}`);
        }catch(e){console.error(`[recategorize] ${row.id} err:`,e.message);}
        await new Promise(r=>setTimeout(r,3000));
      }
      console.log('[recategorize] Done. Distribution:', JSON.stringify(stats));
    }catch(e){console.error('[recategorize] fatal:',e.message);}
    _recategorizeRunning=false;
  })();
});

