// GET /admin/rank-spread-votes?key=… — assign votes based on leaderboard rank so top
// listings are clearly ahead (power-law decay: #1=30, #2=26, #3=23, #4=20 … #10=10).
// Never reduces votes. Safe to re-run.
app.get('/admin/rank-spread-votes', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.flushHeaders();
  const log = m => { console.log(m); res.write(m + '\n'); };
  try {
    // Rank all non-promoted auto-imported active listings by current vote_count DESC.
    // Target = ROUND(30 * 0.88^(rank-1)) but at least 8.  Never reduces.
    const { rowCount } = await pool.query(`
      WITH ranked AS (
        SELECT id, vote_count,
          ROW_NUMBER() OVER (ORDER BY vote_count DESC, submitted_at DESC) AS rn
        FROM directory_listings
        WHERE is_auto_imported = TRUE AND status = 'active'
          AND NOT COALESCE(is_promoted, FALSE)
      ),
      targets AS (
        SELECT id, vote_count,
          GREATEST(
            vote_count,
            GREATEST(8, ROUND(60.0 * POWER(0.85, rn - 1))::INT)
          ) AS target
        FROM ranked
      )
      UPDATE directory_listings dl
      SET vote_count = t.target
      FROM targets t
      WHERE dl.id = t.id AND t.target > dl.vote_count
    `);
    log(`Updated ${rowCount} listings with rank-based spread.`);

    // Show top 15 result
    const { rows } = await pool.query(`
      SELECT name, vote_count,
        ROW_NUMBER() OVER (ORDER BY vote_count DESC, submitted_at DESC) AS rank
      FROM directory_listings
      WHERE is_auto_imported = TRUE AND status = 'active'
        AND NOT COALESCE(is_promoted, FALSE)
      ORDER BY vote_count DESC, submitted_at DESC
      LIMIT 15
    `);
    log('\nTop 15 after spread:');
    rows.forEach(r => log(`  #${r.rank} ${r.name} → ${r.vote_count} votes`));
    log('\nDone.');
  } catch(e) { log(`ERROR: ${e.message}`); }
  res.end();
});

// GET /admin/redistribute-votes?key=… — one-time fix: spread auto-imported vote counts
// from flat 3-10 cluster to a deterministic varied range 4-20 (never reduces anyone's votes)
app.get('/admin/redistribute-votes', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  res.setHeader('Content-Type', 'text/plain');
  res.flushHeaders();
  const log = m => { console.log(m); res.write(m + '\n'); };
  try {
    // Pass 1: raise 3-10 zone → 4-20 via hash
    const r1 = await pool.query(`
      UPDATE directory_listings
      SET vote_count = 4 + ((id * 1013) % 17)
      WHERE is_auto_imported = TRUE AND status = 'active'
        AND vote_count BETWEEN 3 AND 10
        AND (4 + ((id * 1013) % 17)) > vote_count
    `);
    log(`Pass 1 (raise 3-10 → 4-20): ${r1.rowCount} rows updated`);

    // Pass 2: widen the 7-10 band further via second hash → 6-22
    const r2 = await pool.query(`
      UPDATE directory_listings
      SET vote_count = 6 + ((id * 773) % 17)
      WHERE is_auto_imported = TRUE AND status = 'active'
        AND vote_count BETWEEN 7 AND 10
        AND (6 + ((id * 773) % 17)) > vote_count
    `);
    log(`Pass 2 (widen 7-10 → 6-22): ${r2.rowCount} rows updated`);

    // Report new distribution
    const { rows } = await pool.query(`
      SELECT vote_count, COUNT(*) as cnt
      FROM directory_listings
      WHERE is_auto_imported = TRUE AND status = 'active'
      GROUP BY vote_count ORDER BY vote_count DESC LIMIT 25
    `);
    log('\nNew distribution:');
    rows.forEach(r => log(`  ${String(r.vote_count).padStart(3)} → ${r.cnt}`));
    log('\nDone.');
  } catch (e) {
    log(`ERROR: ${e.message}`);
  }
  res.end();
});

// GET /admin/toggle-promoted?key=&id=&promoted=true|false — set is_promoted on a listing
// e.g. /admin/toggle-promoted?key=X&id=199&promoted=true
app.get('/admin/toggle-promoted', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  const id = parseInt(req.query.id, 10);
  const promoted = req.query.promoted === 'true';
  if (!id) return res.status(400).json({ error: 'id required' });
  try {
    const { rows } = await pool.query(
      `UPDATE directory_listings SET is_promoted = $1 WHERE id = $2 RETURNING id, name, is_promoted`,
      [promoted, id]
    );
    if (!rows.length) return res.status(404).json({ error: 'listing not found' });
    res.json({ ok: true, id: rows[0].id, name: rows[0].name, is_promoted: rows[0].is_promoted });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /admin/seed-votes?key=… — seeds vote_count + dir_votes (safe to re-run on any env)
// Period rules:
//   Daily   — only WHY Audit (#1) and SFA (#2) have today's votes; others appear with 0
//   Weekly  — WHY/SFA dominate; ~top-30 other listings get 1-2 weekly votes for realism
//   All-time — full power-law distribution, max 14 for non-owners
app.get('/admin/seed-votes', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  res.setHeader('Content-Type', 'text/plain');
  res.flushHeaders();
  const log = m => { console.log(m); res.write(m + '\n'); };
  try {
    // ── 0. Helpers ─────────────────────────────────────────────────────────────
    function rndMs(minH, maxH) {
      return (minH + Math.random() * (maxH - minH)) * 3600000;
    }
    // Returns array of [listing_id, voter_hash, voted_at_Date] rows
    function makeBucket(id, prefix, n, bucket) {
      const rows = [];
      for (let i = 0; i < n; i++) {
        const ms = bucket === 'today' ? rndMs(0.5, 20)
                 : bucket === 'tw'    ? rndMs(24,  119)
                 : bucket === 'lw'    ? rndMs(168, 311)
                 :                      rndMs(336, 1440);
        rows.push([id, `${prefix}_${i}_${Math.random().toString(36).slice(2)}`, new Date(Date.now() - ms)]);
      }
      return rows;
    }

    // ── 1. vote_count column ────────────────────────────────────────────────────
    // WHY, Strategic Flow Audit and the legacy Blink Test listing are excluded
    // from synthetic seeding; their existing vote counts stay untouched.

    // ── 2. Specific vote_counts for key non-owner listings ──────────────────────
    // All under half of premium (<24), directory is new
    const specificVC = [
      {id:543,vc:18},{id:165,vc:16},{id:248,vc:14},{id:111,vc:13},
      {id:55,vc:12}, {id:163,vc:11},{id:234,vc:7}, {id:457,vc:7},
      {id:474,vc:6}, {id:576,vc:5}, {id:219,vc:5}, {id:577,vc:4},
    ];
    for (const {id,vc} of specificVC) {
      await pool.query(`UPDATE directory_listings SET vote_count=$1 WHERE id=$2`, [vc, id]);
    }

    // Reset remaining non-owner listings to power-law distribution
    const { rows: nonOwners } = await pool.query(
      `SELECT id FROM directory_listings WHERE status='active'
       AND id <> ALL($1::int[])
       AND id NOT IN (${specificVC.map(x=>x.id).join(',')}) ORDER BY random()`,
      [Array.from(SEED_VOTE_DISABLED_IDS)]
    );
    // Directory is new: max 5 votes for non-key listings, power-law skewed to 1-2
    const vcCases = nonOwners.map((r, i) => ({
      id: r.id,
      v: i < 10
        ? [5,5,4,4,4,3,3,3,2,2][i]
        : Math.max(1, Math.floor(Math.pow(Math.random(), 2) * 4) + 1)
    }));
    for (let b = 0; b < vcCases.length; b += 500) {
      const chunk = vcCases.slice(b, b+500);
      const caseStr = chunk.map(c=>`WHEN id=${c.id} THEN ${c.v}`).join(' ');
      await pool.query(
        `UPDATE directory_listings SET vote_count=CASE ${caseStr} END WHERE id=ANY($1::int[])`,
        [chunk.map(c=>c.id)]
      );
    }
    log(`vote_count set for all listings.`);

    // ── 3. Clear old seeded dir_votes ───────────────────────────────────────────
    await pool.query(
      `DELETE FROM dir_votes
       WHERE voter_hash LIKE 'seed_%' AND listing_id <> ALL($1::int[])`,
      [Array.from(SEED_VOTE_DISABLED_IDS)]
    );
    log('Old seed votes cleared for eligible listings; protected listings preserved.');

    // ── 4. Re-insert with full period distribution ───────────────────────────────
    // Key listings: exact buckets matching dev distribution
    // today=daily, tw=this-week-not-today, lw=last-week, old=older
    // Directory is new — keep numbers small and believable
    const keyListings = [
      {id:543, today:0, tw:5,  lw:4,  old:9},   // Twillot          total=18
      {id:165, today:0, tw:4,  lw:3,  old:9},   // Laike AI         total=16
      {id:248, today:0, tw:3,  lw:2,  old:9},   // Neon             total=14
      // {id:111} Deep Wave removed — non-SaaS listing
      {id:55,  today:0, tw:3,  lw:2,  old:7},   // xaicreator       total=12
      {id:163, today:0, tw:3,  lw:2,  old:6},   // Canva            total=11
      {id:234, today:0, tw:2,  lw:1,  old:4},   // NotebookLM       total=7
      {id:457, today:0, tw:2,  lw:1,  old:4},   // Juchats          total=7
      {id:474, today:0, tw:1,  lw:1,  old:4},   // SimilarLabs      total=6
      {id:576, today:0, tw:1,  lw:1,  old:3},   // Shipixen         total=5
      {id:219, today:0, tw:1,  lw:0,  old:4},   // Rollout          total=5
      {id:577, today:0, tw:1,  lw:0,  old:3},   // Proxied          total=4
    ];
    const keyIds = new Set(keyListings.map(x=>x.id));

    // Helper: insert rows using fully parameterized query (avoids FK/syntax issues)
    async function insertVoteRows(rows) {
      for (let b = 0; b < rows.length; b += 50) {
        const chunk = rows.slice(b, b + 50);
        const ph    = chunk.map((_, i) => `($${i*3+1},$${i*3+2},$${i*3+3})`).join(',');
        const params = chunk.flat();
        try {
          await pool.query(
            `INSERT INTO dir_votes (listing_id,voter_hash,voted_at) VALUES ${ph} ON CONFLICT DO NOTHING`,
            params
          );
        } catch(e) {
          log(`WARN insert chunk lid=${chunk[0][0]}: ${e.message}`);
        }
      }
    }

    for (const {id,today,tw,lw,old} of keyListings) {
      // Verify listing exists before inserting
      const {rows:[{c}]} = await pool.query(`SELECT COUNT(*)::int AS c FROM directory_listings WHERE id=$1`,[id]);
      if (!c) { log(`SKIP id=${id} not found`); continue; }
      const rows = [
        ...makeBucket(id,`seed_${id}_td`,today,'today'),
        ...makeBucket(id,`seed_${id}_tw`,tw,   'tw'),
        ...makeBucket(id,`seed_${id}_lw`,lw,   'lw'),
        ...makeBucket(id,`seed_${id}_ol`,old,  'old'),
      ];
      await insertVoteRows(rows);
    }
    log(`Key listing votes inserted.`);

    // All other listings: pick ~30 to have 1–2 weekly votes, rest all older
    const { rows: others } = await pool.query(
      `SELECT id, vote_count FROM directory_listings
       WHERE status='active' AND id!=ALL($1) AND id <> ALL($2::int[]) AND vote_count>0
       ORDER BY vote_count DESC`,
      [Array.from(keyIds), Array.from(SEED_VOTE_DISABLED_IDS)]
    );
    // Only ~10 non-key listings get 1-2 weekly votes; rest are all-old (directory is new)
    const weeklyExtra = new Set(
      others.filter(r=>r.vote_count>=4).sort(()=>Math.random()-0.5).slice(0,10).map(r=>r.id)
    );
    for (const r of others) {
      const n  = r.vote_count;
      const wv = weeklyExtra.has(r.id) ? (n>=10?2:1) : 0;
      const rows = [
        ...(wv > 0 ? makeBucket(r.id,`seed_${r.id}_tw`,wv,'tw') : []),
        ...makeBucket(r.id,`seed_${r.id}_ol`,n-wv,'old'),
      ];
      await insertVoteRows(rows);
    }

    // ── 5. Sync vote_count from real dir_votes ───────────────────────────────────
    await pool.query(`
      UPDATE directory_listings dl
      SET vote_count = sub.real_count
      FROM (SELECT listing_id, COUNT(*)::int AS real_count FROM dir_votes GROUP BY listing_id) sub
      WHERE dl.id = sub.listing_id
    `);
    log('vote_count synced from dir_votes.');

    log('Protected owner listings were not seeded or overwritten.');

    // ── 6. Sanity check ──────────────────────────────────────────────────────────
    const { rows: [{ n: cnt }] } = await pool.query(`SELECT COUNT(*) n FROM dir_votes`);
    const checks = await pool.query(`
      SELECT
        (SELECT COUNT(*)::int FROM dir_votes WHERE voted_at >= date_trunc('day',  NOW() AT TIME ZONE 'UTC') AND listing_id=199) AS why_daily,
        (SELECT COUNT(*)::int FROM dir_votes WHERE voted_at >= date_trunc('day',  NOW() AT TIME ZONE 'UTC') AND listing_id=203) AS sfa_daily,
        (SELECT COUNT(*)::int FROM dir_votes WHERE voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC') AND listing_id=199) AS why_weekly,
        (SELECT COUNT(*)::int FROM dir_votes WHERE voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC') AND listing_id=203) AS sfa_weekly,
        (SELECT COUNT(DISTINCT listing_id)::int FROM dir_votes
          WHERE voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC') AND listing_id NOT IN (199,203)) AS other_in_weekly
    `);
    const c = checks.rows[0];
    log(`Total dir_votes: ${cnt}`);
    log(`Daily  → WHY:${c.why_daily}  SFA:${c.sfa_daily}`);
    log(`Weekly → WHY:${c.why_weekly}  SFA:${c.sfa_weekly}  other_products:${c.other_in_weekly}`);

    res.end('\n[DONE]');
  } catch(e) {
    log('ERROR: ' + e.message);
    res.end('\n[FAILED]');
  }
});

// GET /admin/score?key=…&reset_seeded=1
// Optional reset_seeded=1 nulls out hardcoded seed scores so real DFM runs.
// Scores up to 50 pending/unscored listings, 3s apart.
app.get('/admin/score', async (req, res) => {
  if (req.query.key !== process.env.WHY_ADMIN_KEY) return res.status(403).json({ error: 'forbidden' });
  res.json({ ok: true, message: 'Scoring run started in background — check server logs.' });
  setImmediate(async () => {
    try {
      if (req.query.reset_seeded === '1') {
        await pool.query(
          `UPDATE directory_listings
           SET friction_score = NULL, score_pending = TRUE, scored_at = NULL
           WHERE is_seeded = TRUE`
        );
        console.log('[admin/score] Reset seeded listing scores to pending.');
      }
      const r = await pool.query(
        `SELECT id, url FROM directory_listings
         WHERE (score_pending = TRUE OR friction_score IS NULL) AND status = 'active'
         ORDER BY submitted_at ASC LIMIT 50`
      );
      console.log(`[admin/score] Scoring ${r.rows.length} listings…`);
      for (const row of r.rows) {
        await computeDirectoryFrictionScore(row.id, row.url).catch(e =>
          console.error(`[admin/score] id=${row.id} error:`, e.message)
        );
        await new Promise(res => setTimeout(res, 3000));
      }
      console.log('[admin/score] Batch done.');
    } catch(e) { console.error('[admin/score] Fatal:', e.message); }
  });
});

