// ── Directory: compute current period winners from dir_votes ─────────────────
// Cached for 5 minutes to reduce DB load on high-traffic badge requests.
let _winnersCache = { data: null, at: 0 };
const WINNERS_TTL = 5 * 60 * 1000;

async function computeWinners() {
  if (_winnersCache.data && Date.now() - _winnersCache.at < WINNERS_TTL) return _winnersCache.data;
  try {
    const r = await pool.query(`
      SELECT
        (SELECT listing_id FROM dir_votes
         WHERE voted_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')
           AND voted_at <= NOW() AT TIME ZONE 'UTC'
         GROUP BY listing_id ORDER BY COUNT(*) DESC, listing_id ASC LIMIT 1) AS day_winner,
        (SELECT listing_id FROM dir_votes
         WHERE voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC')
           AND voted_at <= NOW() AT TIME ZONE 'UTC'
         GROUP BY listing_id ORDER BY COUNT(*) DESC, listing_id ASC LIMIT 1) AS week_winner,
        (SELECT listing_id FROM dir_votes
         WHERE voted_at >= date_trunc('month', NOW() AT TIME ZONE 'UTC')
           AND voted_at <= NOW() AT TIME ZONE 'UTC'
         GROUP BY listing_id ORDER BY COUNT(*) DESC, listing_id ASC LIMIT 1) AS month_winner
    `);
    const row = r.rows[0] || {};
    const data = { day: row.day_winner || null, week: row.week_winner || null, month: row.month_winner || null };
    _winnersCache = { data, at: Date.now() };
    return data;
  } catch(e) {
    console.error('[computeWinners]', e.message);
    return _winnersCache.data || { day: null, week: null, month: null };
  }
}

// ── Directory: compute winner for a fully-closed explicit time range ────────────
// Used by archival crons that run AFTER the period ends so the interval is exact.
// Returns listing_id | null. Tie-break: lower id wins (stable across runs).
async function computeWinnerForRange(start, end) {
  try {
    const r = await pool.query(
      `SELECT listing_id, COUNT(*)::int AS cnt
       FROM dir_votes
       WHERE voted_at >= $1 AND voted_at <= $2
       GROUP BY listing_id
       ORDER BY cnt DESC, listing_id ASC
       LIMIT 1`,
      [start.toISOString(), end.toISOString()]
    );
    return r.rows.length > 0 ? r.rows[0].listing_id : null;
  } catch(e) {
    console.error('[computeWinnerForRange]', e.message);
    return null;
  }
}

// ── Directory: compute trending listings ──────────────────────────────────────
// Eligible: ≥3 votes in last 24h AND more than previous 24h. Cached 5 min.
let _trendingCache = { data: null, at: 0 };
const TRENDING_TTL = 5 * 60 * 1000;

async function computeTrending() {
  if (_trendingCache.data && Date.now() - _trendingCache.at < TRENDING_TTL) return _trendingCache.data;
  try {
    const r = await pool.query(`
      SELECT
        listing_id AS id,
        COUNT(*) FILTER (WHERE voted_at >= NOW() - INTERVAL '24 hours'
                           AND voted_at <= NOW())::int  AS cur,
        COUNT(*) FILTER (WHERE voted_at >= NOW() - INTERVAL '48 hours'
                           AND voted_at <  NOW() - INTERVAL '24 hours')::int  AS prev
      FROM dir_votes
      WHERE voted_at >= NOW() - INTERVAL '48 hours'
        AND voted_at <= NOW()
      GROUP BY listing_id
      HAVING COUNT(*) FILTER (WHERE voted_at >= NOW() - INTERVAL '24 hours'
                                AND voted_at <= NOW()) >= 3
    `);
    const data = r.rows
      .filter(row => row.cur > row.prev)
      .map(row => ({
        id:   row.id,
        cur:  row.cur,
        prev: row.prev,
        pct:  row.prev > 0 ? Math.round(((row.cur - row.prev) / row.prev) * 100) : 100,
      }))
      .sort((a, b) => b.pct - a.pct);
    _trendingCache = { data, at: Date.now() };
    return data;
  } catch(e) {
    console.error('[computeTrending]', e.message);
    return _trendingCache.data || [];
  }
}

// ── Directory: expire stale featured placements ───────────────────────────────
async function expireFeaturedListings() {
  try {
    const expired = await pool.query(
      `UPDATE dir_featured SET is_active=FALSE
       WHERE is_active=TRUE AND expires_at < NOW()
       RETURNING listing_id`
    );
    for (const row of expired.rows) {
      // Clear featured_tier on the listing only if no other active placement remains
      const still = await pool.query(
        `SELECT id FROM dir_featured WHERE listing_id=$1 AND is_active=TRUE LIMIT 1`,
        [row.listing_id]
      );
      if (still.rows.length === 0) {
        await pool.query(
          `UPDATE directory_listings SET featured_tier=NULL, featured_until=NULL WHERE id=$1`,
          [row.listing_id]
        );
      }
    }
    if (expired.rows.length > 0) console.log(`[dir-featured] expired ${expired.rows.length} placements`);
  } catch(e) { console.error('[dir-featured] expiry error:', e.message); }
}

