// ── GET /sponsor — SSR sponsor page ───────────────────────────────────────────
app.get('/sponsor', async (req, res) => {
  try {
    const categoryRows = await pool.query(`
      SELECT category, COUNT(*)::int AS listing_count
      FROM directory_listings
      WHERE status='active' AND category IS NOT NULL AND TRIM(category) <> ''
      GROUP BY category
      ORDER BY listing_count DESC, category ASC
    `);
    const categories = categoryRows.rows.map(row => row.category);
    const requestedCategory = typeof req.query.category === 'string' ? req.query.category.trim() : '';
    const selectedCategory = categories.includes(requestedCategory) ? requestedCategory : (categories[0] || 'General');
    const r = await pool.query(
      `SELECT id, sponsor_name, sponsor_url, sponsor_logo, sponsor_tagline, sponsor_category
       FROM dir_sponsors WHERE is_active=TRUE AND expires_at > NOW()
       ORDER BY created_at ASC LIMIT 100`
    );
    const sponsors        = r.rows;
    const categoryActive = await pool.query(
      `SELECT COUNT(*)::int AS n FROM dir_sponsors
       WHERE is_active=TRUE AND expires_at > NOW()
         AND (sponsor_category=$1 OR sponsor_category IS NULL)`,
      [selectedCategory]
    );
    const slots_available = Math.max(0, SPONSOR_MAX_SLOTS - Number(categoryActive.rows[0]?.n || 0));
    let html = require('fs').readFileSync(path.join(__dirname, 'public/sponsor.html'), 'utf8');
    const safe = s => JSON.stringify(s).replace(/<\/script>/gi, '<\\/script>');
    html = html.replace('</head>',
      `<script>window.__SSR_SPONSORS__=${safe(sponsors)};window.__SSR_SLOTS__=${slots_available};window.__SSR_CATEGORIES__=${safe(categoryRows.rows)};window.__SSR_CATEGORY__=${safe(selectedCategory)};</script>\n</head>`);
    // Inject live count into sponsor page hero + meta
    const sponsorCount = await getActiveListingCount();
    const sponsorCountStr = sponsorCount + '+';
    html = html.replace(/\b500\+/g, sponsorCountStr).replace(/\b544\+/g, sponsorCountStr).replace(/\b566\+/g, sponsorCountStr);
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(html);
  } catch(err) {
    console.error('[sponsor-ssr]', err.message);
    res.sendFile(path.join(__dirname, 'public/sponsor.html'));
  }
});

// ── POST /api/directory/checkout ──────────────────────────────────────────────
app.post('/api/directory/checkout', async (req, res) => {
  const { listing_id, tier, email, boost_date } = req.body || {};
  const payerEmail = String(email || '').trim().toLowerCase();
  const listingId = Number(listing_id);
  const auditListingId = Number.isSafeInteger(listingId) && listingId > 0 ? listingId : null;
  if (!auditListingId || !DIR_PRICES[tier]) {
    await writeSecurityAudit('directory_checkout_rejected', {
      actorType: 'public',
      listingId: auditListingId,
      actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payerEmail) ? payerEmail : null,
      metadata: { reason: 'invalid_params', tier: String(tier || '').slice(0, 40) }
    });
    return res.status(400).json({ error: 'invalid_params' });
  }
  if (payerEmail && isBlockedDirectoryEmail(payerEmail)) {
    await writeSecurityAudit('directory_checkout_rejected', {
      actorType: 'public',
      listingId: auditListingId,
      actorEmail: payerEmail,
      metadata: { reason: 'permanent_email_block', domain: 'datafreak.net', tier }
    });
    return res.status(403).json({ error: 'email_blocked' });
  }
  const listingRow = await pool.query('SELECT id, name, claimed_by FROM directory_listings WHERE id=$1 AND status=\'active\'', [auditListingId]).catch(() => null);
  if (!listingRow?.rows?.length) {
    await writeSecurityAudit('directory_checkout_rejected', {
      actorType: 'public', listingId: auditListingId,
      actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payerEmail) ? payerEmail : null,
      metadata: { reason: 'listing_not_found', tier }
    });
    return res.status(404).json({ error: 'listing_not_found' });
  }
  let claimOwnerEmail = null;

  if (tier === 'verified_badge') {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payerEmail)) {
      await writeSecurityAudit('directory_checkout_rejected', {
        actorType: 'public', listingId: auditListingId,
        metadata: { reason: 'ownership_required', tier }
      });
      return res.status(403).json({ error: 'ownership_required' });
    }
    const claim = await authorizeDirectoryClaim(req, auditListingId, payerEmail);
    if (!claim || String(listingRow.rows[0].claimed_by || '').toLowerCase() !== payerEmail) {
      await writeSecurityAudit('directory_checkout_rejected', {
        actorType: 'public', listingId: auditListingId, actorEmail: payerEmail,
        metadata: { reason: 'ownership_required', tier }
      });
      return res.status(403).json({ error: 'ownership_required' });
    }
    claimOwnerEmail = payerEmail;
  }

  // ── Daily Boost: validate the requested date is not already booked ─────────
  if (tier === 'daily_top') {
    const targetDate = boost_date || new Date().toISOString().slice(0, 10);
    const dateRe = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRe.test(targetDate)) {
      await writeSecurityAudit('directory_checkout_rejected', {
        actorType: 'public', listingId: auditListingId, actorEmail: payerEmail || null,
        metadata: { reason: 'invalid_date', tier }
      });
      return res.status(400).json({ error: 'invalid_date' });
    }
    if (targetDate < new Date().toISOString().slice(0, 10)) {
      await writeSecurityAudit('directory_checkout_rejected', {
        actorType: 'public', listingId: auditListingId, actorEmail: payerEmail || null,
        metadata: { reason: 'date_in_past', tier, boost_date: targetDate }
      });
      return res.status(400).json({ error: 'date_in_past' });
    }
    // No per-day slot limit — multiple listings can boost on the same date
  }

  try {
    const base = process.env.APP_URL || 'https://strategic-flow-audit.replit.app';
    const targetDate = (tier === 'daily_top' && boost_date) ? boost_date : new Date().toISOString().slice(0, 10);
    const sess = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      mode: 'payment',
      line_items: [{ price: DIR_PRICES[tier].price_id, quantity: 1 }],
      success_url: `${base}/directory?boosted=1&tier=${tier}&lid=${listing_id}`,
      cancel_url:  `${base}/directory`,
      customer_email: payerEmail.includes('@') ? payerEmail : undefined,
      metadata: {
        source: 'directory', listing_id: String(auditListingId), tier,
        listing_name: listingRow.rows[0].name.slice(0, 80),
        ...(claimOwnerEmail ? { claim_owner_email: claimOwnerEmail } : {}),
        ...(tier === 'daily_top' ? { boost_date: targetDate } : {}),
      },
    });
    await writeSecurityAudit('directory_checkout_created', {
      actorType: 'public',
      listingId: auditListingId,
      actorEmail: payerEmail || null,
      metadata: { tier, session_id: sess.id, ...(tier === 'daily_top' ? { boost_date: targetDate } : {}) }
    });
    res.json({ url: sess.url });
  } catch(err) {
    console.error('[dir-checkout]', err.message);
    await writeSecurityAudit('directory_checkout_failed', {
      actorType: 'public',
      listingId: auditListingId,
      actorEmail: payerEmail || null,
      metadata: { tier, reason: String(err.message || err).slice(0, 200) }
    });
    res.status(500).json({ error: 'checkout_failed' });
  }
});

// ── GET /api/directory/activity-feed ─────────────────────────────────────────
app.get('/api/directory/activity-feed', async (req, res) => {
  try {
    const [eventsRes, top3Res] = await Promise.all([
      pool.query(`
        (SELECT 'claimed' AS type, dl.name, dc.verified_at AS occurred_at, NULL::text AS detail, dl.id
         FROM dir_claims dc JOIN directory_listings dl ON dl.id=dc.listing_id
         WHERE dc.is_verified=TRUE AND dc.verified_at IS NOT NULL
         ORDER BY dc.verified_at DESC LIMIT 8)
        UNION ALL
        (SELECT 'joined', dl.name, dl.submitted_at, NULL, dl.id
         FROM directory_listings dl
         WHERE dl.status='active' AND NOT dl.is_seeded
           AND dl.submitted_at > NOW() - INTERVAL '30 days'
         ORDER BY dl.submitted_at DESC LIMIT 8)
        UNION ALL
        (SELECT 'boosted', dl.name, df.starts_at, df.tier, dl.id
         FROM dir_featured df JOIN directory_listings dl ON dl.id=df.listing_id
         WHERE df.starts_at > NOW() - INTERVAL '14 days'
         ORDER BY df.starts_at DESC LIMIT 6)
        UNION ALL
        (SELECT 'climbed' AS type, dl.name,
                NOW() - INTERVAL '1 minute' * (row_number() OVER (ORDER BY cur_votes DESC)) AS occurred_at,
                '#' || RANK() OVER (ORDER BY dl.vote_count DESC)::text AS detail,
                dl.id
         FROM directory_listings dl
         JOIN LATERAL (
           SELECT COUNT(*)::int AS cur_votes
           FROM dir_votes
           WHERE listing_id=dl.id AND voted_at >= NOW() - INTERVAL '24 hours'
         ) v ON true
         WHERE dl.status='active'
           AND v.cur_votes >= 3
           AND v.cur_votes > (
             SELECT COUNT(*)::int FROM dir_votes
             WHERE listing_id=dl.id
               AND voted_at >= NOW() - INTERVAL '48 hours'
               AND voted_at < NOW() - INTERVAL '24 hours'
           )
         ORDER BY v.cur_votes DESC LIMIT 4)
        UNION ALL
        (SELECT 'velocity' AS type, dl.name,
                MAX(dv.voted_at) AS occurred_at,
                COUNT(dv.id)::text AS detail,
                dl.id
         FROM dir_votes dv
         JOIN directory_listings dl ON dl.id = dv.listing_id
         WHERE dl.status = 'active'
           AND dv.voted_at >= NOW() - INTERVAL '1 hour'
         GROUP BY dl.id, dl.name
         HAVING COUNT(dv.id) >= 2
         ORDER BY COUNT(dv.id) DESC LIMIT 3)
        UNION ALL
        (SELECT 'recent_claim' AS type, dl.name,
                dl.claimed_at AS occurred_at,
                NULL::text AS detail,
                dl.id
         FROM directory_listings dl
         WHERE dl.claimed_at >= NOW() - INTERVAL '6 hours'
           AND dl.status = 'active'
         ORDER BY dl.claimed_at DESC LIMIT 3)
        ORDER BY occurred_at DESC LIMIT 20
      `),
      pool.query(`
        WITH today AS (
          SELECT dl.id, dl.name, COUNT(dv.id)::int AS votes
          FROM dir_votes dv JOIN directory_listings dl ON dl.id=dv.listing_id
          WHERE dl.status='active'
            AND dv.voted_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')
            AND dv.voter_hash NOT LIKE 'daily_growth_%'
            AND dv.voter_hash NOT LIKE 'claimed_boost_%'
            AND dv.voter_hash NOT LIKE 'seed_%'
          GROUP BY dl.id, dl.name ORDER BY votes DESC LIMIT 3
        ),
        fallback AS (
          SELECT dl.id, dl.name, COUNT(dv.id)::int AS votes
          FROM dir_votes dv JOIN directory_listings dl ON dl.id=dv.listing_id
          WHERE dl.status='active'
            AND dv.voted_at >= NOW() - INTERVAL '7 days'
            AND dv.voter_hash NOT LIKE 'daily_growth_%'
            AND dv.voter_hash NOT LIKE 'claimed_boost_%'
            AND dv.voter_hash NOT LIKE 'seed_%'
          GROUP BY dl.id, dl.name ORDER BY votes DESC LIMIT 3
        )
        SELECT *, (SELECT COUNT(*) FROM today) > 0 AS is_today
        FROM (
          SELECT * FROM today
          UNION ALL
          SELECT id, name, votes FROM fallback WHERE (SELECT COUNT(*) FROM today) = 0
        ) t LIMIT 3
      `),
    ]);
    const top3 = top3Res.rows;
    const top3Period = top3.length > 0 && top3[0].is_today ? 'today' : '7d';
    res.json({ events: eventsRes.rows, top3, top3Period });
  } catch(e) {
    console.error('[activity-feed]', e.message);
    res.status(500).json({ events: [], top3: [] });
  }
});

// ── GET /api/directory/activity-stats — real submission + claim counts ─────────
app.get('/api/directory/activity-stats', async (req, res) => {
  res.set('Cache-Control', 'public, max-age=120'); // 2-min cache
  try {
    const [statsRes, nearRes] = await Promise.all([
      pool.query(`
        SELECT
          (SELECT COUNT(*)::int FROM directory_listings
           WHERE status='active' AND NOT is_seeded
             AND submitted_at >= NOW() - INTERVAL '24 hours') AS submitted_24h,
          (SELECT COUNT(*)::int FROM directory_listings
           WHERE status='active'
             AND claimed_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')) AS claimed_today
      `),
      pool.query(`
        WITH ranked AS (
          SELECT dl.id, dl.name, COUNT(dv.id)::int AS today_votes
          FROM directory_listings dl
          JOIN dir_votes dv ON dv.listing_id = dl.id
          WHERE dl.status = 'active'
            AND dv.voted_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')
          GROUP BY dl.id, dl.name
          ORDER BY today_votes DESC
          LIMIT 12
        ),
        threshold AS (
          SELECT MIN(today_votes) AS cutoff, COUNT(*)::int AS cnt
          FROM (SELECT today_votes FROM ranked ORDER BY today_votes DESC LIMIT 10) t
        )
        SELECT r.id, r.name,
               (t.cutoff - r.today_votes) AS votes_needed
        FROM ranked r, threshold t
        WHERE t.cnt >= 8
          AND r.today_votes < t.cutoff
          AND (t.cutoff - r.today_votes) BETWEEN 1 AND 5
        ORDER BY votes_needed ASC
        LIMIT 5
      `),
    ]);
    const stats = statsRes.rows[0] || {};
    res.json({
      submitted_24h: stats.submitted_24h || 0,
      claimed_today: stats.claimed_today || 0,
      near_top10: nearRes.rows.map(r => ({ id: r.id, votes_needed: parseInt(r.votes_needed) })),
    });
  } catch(e) {
    console.error('[activity-stats]', e.message);
    res.status(500).json({ submitted_24h: 0, claimed_today: 0, near_top10: [] });
  }
});

