// ── POST /api/directory/vote/:id ──────────────────────────────────────────────
app.options('/api/directory/vote/:id', (req, res) => {
  applyTrustedCors(req, res, 'POST, OPTIONS');
  res.sendStatus(204);
});

app.post('/api/directory/vote/:id', directoryEventCors, async (req, res) => {
  const lid = parseInt(req.params.id, 10);
  if (!lid) return res.status(400).json({ error: 'bad_id' });
  if (!hasTrustedDirectoryEventOrigin(req)) {
    return rejectDirectoryAbuse(req, res, 'vote', lid, 'untrusted_origin', 403);
  }

  try {
    const listing = await pool.query('SELECT id, vote_count FROM directory_listings WHERE id=$1 AND status=\'active\'', [lid]);
    if (!listing.rows.length) return res.status(404).json({ error: 'not_found' });
    const identity = directoryEventIdentity(req, res);
    if (!identity) return res.status(503).json({ error: 'temporarily_unavailable' });
    const hash = claimCredentialHash('vote', `${identity.visitorHash}:${lid}`);
    const existingVote = await pool.query(
      'SELECT 1 FROM dir_votes WHERE listing_id=$1 AND voter_hash=$2',
      [lid, hash]
    );
    if (existingVote.rows.length) {
      return res.status(409).json({ error: 'already_voted', vote_count: listing.rows[0].vote_count });
    }
    const [ipAllowed, visitorAllowed, listingIpAllowed] = await Promise.all([
      consumeDirectoryRateLimit(`directory-vote-ip:${identity.ipHash}`, 6, 60 * 60),
      consumeDirectoryRateLimit(`directory-vote-visitor:${identity.visitorHash}`, 3, 24 * 60 * 60),
      consumeDirectoryRateLimit(`directory-vote-listing-ip:${lid}:${identity.ipHash}`, 1, 24 * 60 * 60)
    ]);
    if (!ipAllowed || !visitorAllowed || !listingIpAllowed) {
      const reason = !ipAllowed ? 'ip_rate_limit'
        : !visitorAllowed ? 'visitor_rate_limit' : 'listing_ip_rate_limit';
      return rejectDirectoryAbuse(req, res, 'vote', lid, reason);
    }

    const client = await pool.connect();
    let updated;
    try {
      await client.query('BEGIN');
      const vote = await client.query(
        `INSERT INTO dir_votes (listing_id, voter_hash) VALUES ($1,$2) ON CONFLICT DO NOTHING RETURNING id`,
        [lid, hash]
      );
      if (!vote.rows.length) {
        await client.query('ROLLBACK');
        return res.status(409).json({ error: 'already_voted', vote_count: listing.rows[0].vote_count });
      }
      updated = await client.query(
        `UPDATE directory_listings SET vote_count = vote_count + 1 WHERE id=$1
         RETURNING vote_count, claimed_by, name`,
        [lid]
      );
      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK').catch(() => {});
      throw err;
    } finally {
      client.release();
    }
    const newCount   = updated.rows[0].vote_count;
    const claimedBy  = updated.rows[0].claimed_by;
    const listingName = updated.rows[0].name;
    res.json({ ok: true, vote_count: newCount });

    // Send one-time first-vote notification to verified owner
    if (newCount === 1 && claimedBy) {
      resend.emails.send({
        from:    SENDER,
        replyTo: 'strategicflow@proton.me',
        to:      claimedBy,
        subject: `Your listing "${listingName}" just got its first vote 🎉`,
        html: `<p>Good news — someone upvoted your listing <strong>${listingName}</strong> on the Strategic Flow directory.</p>
               <p><a href="https://strategic-flow-audit.replit.app/directory">View the directory →</a></p>
               <p style="color:#888;font-size:12px;">You're receiving this because you claimed this listing.</p>`
      }).catch(() => {});
    }

    // ── Competitor rank-change notification (max 1 email/listing/day) ──────────
    setImmediate(async () => {
      try {
        const meRow = await pool.query(
          `SELECT dl.category FROM directory_listings dl WHERE dl.id=$1`, [lid]
        );
        if (!meRow.rows.length) return;
        const { category } = meRow.rows[0];

        // Find claimed competitors this listing just overtook (they now have 1 fewer vote)
        const overtaken = await pool.query(
          `SELECT dl.id, dl.name, dc.owner_email,
                  (SELECT COUNT(*)::int FROM directory_listings
                   WHERE status='active' AND category=$2
                     AND vote_count > dl.vote_count) + 1 AS their_rank
           FROM directory_listings dl
           JOIN dir_claims dc ON dc.listing_id=dl.id AND dc.is_verified=TRUE
           JOIN toolindex_newsletter_contacts nc
             ON nc.email=lower(trim(dc.owner_email))
            AND nc.status='confirmed' AND nc.confirmed_at IS NOT NULL
           WHERE dl.status='active' AND dl.category=$2 AND dl.id!=$1
             AND dc.owner_email IS NOT NULL
             AND NOT EXISTS (
               SELECT 1 FROM email_unsubscribes u
               WHERE lower(u.email)=lower(trim(dc.owner_email))
             )
             AND dl.vote_count = $3 - 1`,
          [lid, category, newCount]
        );

        const today = new Date().toISOString().slice(0, 10);
        for (const comp of overtaken.rows) {
          const email = (comp.owner_email || '').toLowerCase();
          if (BYPASS_EMAILS.has(email)) continue;
          // Rate-limit: max 1 rank-change alert per listing per day
          const rlKey = `rank-notif:${comp.id}:${today}`;
          if (_otpRateLimit.has(rlKey)) continue;
          _otpRateLimit.set(rlKey, Date.now());
          resend.emails.send({
            from: SENDER,
            to:   comp.owner_email,
            subject: `${listingName} just passed ${comp.name} in ${category} — you're now #${comp.their_rank}`,
            html: `<div style="font-family:sans-serif;max-width:500px;margin:auto;background:#0a1628;color:#eef1f7;padding:24px;border-radius:12px;border:1px solid rgba(0,212,200,0.2);">
              <p style="color:#00d4c8;font-size:11px;letter-spacing:.1em;text-transform:uppercase;margin:0 0 16px;">ToolIndex — Rank Change Alert</p>
              <h2 style="font-size:18px;margin:0 0 12px;"><strong>${escHtml(listingName)}</strong> moved ahead of <strong>${escHtml(comp.name)}</strong> in <strong>${escHtml(category)}</strong></h2>
              <p style="color:#94a3b8;font-size:14px;line-height:1.6;margin:0 0 16px;">Your listing is now <strong>#${comp.their_rank}</strong> in this category. A Daily Boost ($9) pins you back to #1 for 24 hours.</p>
              <a href="https://strategic-flow-audit.replit.app/directory" style="display:inline-block;margin-top:8px;padding:10px 20px;background:#00d4c8;color:#041214;border-radius:8px;text-decoration:none;font-weight:700;font-size:13px;">Reclaim your spot →</a>
              ${buildUnsubFooterHtml(comp.owner_email)}
            </div>`
          }).catch(() => {});
          console.log(`[vote-rank-notif] alerted ${comp.name} owner (${email}) — overtaken by ${listingName} in "${category}"`);
        }
      } catch(e) {
        console.error('[vote-rank-notif]', e.message);
      }
    });
  } catch(err) {
    console.error('[dir-vote]', err.message);
    res.status(500).json({ error: 'db_error' });
  }
});

// ── GET /api/directory/recent-launches?interval=24h|7d|30d ───────────────────
app.get('/api/directory/recent-launches', async (req, res) => {
  const interval = req.query.interval || '24h';
  // Whitelist fixed SQL clauses and keep each tab as a non-overlapping bucket.
  const buckets = {
    '24h': `submitted_at >= NOW() - INTERVAL '24 hours'`,
    '7d': `submitted_at >= NOW() - INTERVAL '7 days'
           AND submitted_at < NOW() - INTERVAL '24 hours'`,
    '30d': `submitted_at >= NOW() - INTERVAL '30 days'
            AND submitted_at < NOW() - INTERVAL '7 days'`,
  };
  const bucket = buckets[interval] ? interval : '24h';
  try {
    const r = await pool.query(
      `SELECT id, name, url, category, description, image_url, vote_count, submitted_at
       FROM directory_listings
       WHERE status='active' AND ${buckets[bucket]}
       ORDER BY submitted_at DESC LIMIT 10`
    );
    res.json({ listings: r.rows, interval: bucket });
  } catch(err) {
    console.error('[dir-recent-launches]', err.message);
    res.status(500).json({ error: 'db_error' });
  }
});

