// ── GET /api/directory/leaderboard?period=daily|weekly|all ───────────────────
app.get('/api/directory/leaderboard', async (req, res) => {
  const period = req.query.period || 'all';
  try {
    let q;
    if (period === 'daily') {
      // Daily tab = listings with the most real organic votes cast today.
      // Owner's own apps (199,203,4298) excluded — they're already featured in the grid.
      // Numbers are always <= weekly which are <= all-time.
      q = `SELECT dl.id, dl.name, dl.url, dl.category, dl.description,
                  dl.friction_score, dl.score_pending,
                  CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                       WHEN dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                       ELSE NULL END AS image_url, dl.source, dl.source_url,
                  dl.featured_tier, dl.vote_count, dl.pinned_in_leaderboard,
                  COUNT(dv.id)::int AS period_votes,
                  FALSE                                                                  AS is_founder_pack,
                  (dl.claimed_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')
                   AND dl.claimed_by IS NOT NULL)                                        AS claimed_today
           FROM directory_listings dl
           LEFT JOIN dir_votes dv ON dv.listing_id = dl.id
             AND dv.voted_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC')
             AND dv.voted_at <= NOW() AT TIME ZONE 'UTC'
             AND dv.voter_hash NOT LIKE 'daily_growth_%'
             AND dv.voter_hash NOT LIKE 'claimed_boost_%'
             AND dv.voter_hash NOT LIKE 'seed_%'
           WHERE dl.status='active'
             AND dl.id NOT IN (199,203,4298)
           GROUP BY dl.id
           HAVING COUNT(dv.id) > 0
           ORDER BY period_votes DESC, dl.vote_count DESC
           LIMIT 25`;
    } else if (period === 'weekly') {
      // Weekly: total accumulated votes (synthetic + real) — always larger than daily
      // organic-only count. Owner apps excluded; sorted by all-time vote_count.
      q = `SELECT dl.id, dl.name, dl.url, dl.category, dl.description,
                  dl.friction_score, dl.score_pending,
                   CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                        WHEN dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                        ELSE NULL END AS image_url, dl.source, dl.source_url,
                  dl.featured_tier, dl.vote_count, dl.pinned_in_leaderboard,
                  dl.vote_count                                                          AS period_votes,
                  FALSE                                                                  AS is_founder_pack,
                  (dl.claimed_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC')
                   AND dl.claimed_by IS NOT NULL)                                        AS claimed_today
           FROM directory_listings dl
           WHERE dl.status='active'
             AND dl.id NOT IN (199,203,4298)
             AND dl.vote_count > 0
           ORDER BY dl.vote_count DESC
           LIMIT 25`;
    } else if (period === 'trending') {
      // Biggest vote velocity in the last 24 hours. Pinned listings always appear
      // at the top even if they have no recent activity; unpinned need ≥1 vote.
      q = `SELECT dl.id, dl.name, dl.url, dl.category, dl.description,
                  dl.friction_score, dl.score_pending,
                   CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                        WHEN dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                        ELSE NULL END AS image_url, dl.source, dl.source_url,
                  dl.featured_tier, dl.vote_count, dl.pinned_in_leaderboard,
                  COUNT(dv.id)::int AS period_votes
           FROM directory_listings dl
           LEFT JOIN dir_votes dv ON dv.listing_id = dl.id
             AND dv.voted_at >= NOW() - INTERVAL '24 hours'
             AND dv.voted_at <= NOW() AT TIME ZONE 'UTC'
           WHERE dl.status='active'
           GROUP BY dl.id
           HAVING COUNT(dv.id) > 0
           ORDER BY period_votes DESC, dl.vote_count DESC LIMIT 25`;
    } else if (period === 'new') {
      // Most recently submitted active listings
      q = `SELECT id, name, url, category, description,
                  friction_score, score_pending,
                   CASE WHEN owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || id::text
                        WHEN image_url NOT LIKE '%google.com/s2/favicons%' THEN image_url
                        ELSE NULL END AS image_url, source, source_url,
                  featured_tier, vote_count, pinned_in_leaderboard, 0 AS period_votes,
                  submitted_at
           FROM directory_listings
           WHERE status='active'
           ORDER BY submitted_at DESC LIMIT 25`;
    } else if (period === 'clicked') {
      // Highest outbound click count. Pinned listings always appear at top
      // even with zero clicks; unpinned need ≥1 tracked click.
      q = `SELECT dl.id, dl.name, dl.url, dl.category, dl.description,
                  dl.friction_score, dl.score_pending,
                   CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                        WHEN dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                        ELSE NULL END AS image_url, dl.source, dl.source_url,
                  dl.featured_tier, dl.vote_count, dl.pinned_in_leaderboard,
                  COUNT(dc.id)::int AS period_votes
           FROM directory_listings dl
           LEFT JOIN dir_listing_clicks dc ON dc.listing_id = dl.id
           WHERE dl.status='active'
           GROUP BY dl.id
           HAVING COUNT(dc.id) > 0
           ORDER BY period_votes DESC LIMIT 25`;
    } else {
      q = `SELECT id, name, url, category, description,
                  friction_score, score_pending,
                   CASE WHEN owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || id::text
                        WHEN image_url NOT LIKE '%google.com/s2/favicons%' THEN image_url
                        ELSE NULL END AS image_url, source, source_url,
                  featured_tier, vote_count, pinned_in_leaderboard,
                  vote_count AS period_votes
           FROM directory_listings
           WHERE status='active'
           ORDER BY vote_count DESC LIMIT 25`;
    }
    const r = await pool.query(q);
    res.json({ period, listings: r.rows });
  } catch(err) {
    console.error('[dir-leaderboard]', err.message);
    res.status(500).json({ error: 'db_error' });
  }
});

