// ── POST /api/directory/claim/edit ────────────────────────────────────────────
app.post('/api/directory/claim/edit', async (req, res) => {
  const { listing_id, email,
          description, image_url,
          founder_name, founder_avatar_url, social_twitter, social_linkedin,
          screenshots, tech_stack, platform, pricing_model, launch_date } = req.body || {};
  if (!listing_id)
    return res.status(400).json({ error: 'listing_id required' });

  try {
    const claim = await authorizeDirectoryClaim(req, listing_id, email);
    if (!claim) {
      await writeSecurityAudit('directory_listing_edit_rejected', {
        actorType: 'public',
        listingId: Number.isSafeInteger(Number(listing_id)) ? Number(listing_id) : null,
        actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim()) ? String(email).trim().toLowerCase() : null,
        metadata: { reason: 'unauthorized' }
      });
      return res.status(403).json({ error: 'unauthorized' });
    }

    const beforeState = await getDirectoryListingState(Number(listing_id));
    const updates = [];
    const params  = [];

    if (description && description.trim()) {
      params.push(description.trim().slice(0, 500));
      updates.push(`owner_description=$${params.length}`);
    }
    if (image_url && isAllowedDirectoryImageUrl(image_url)) {
      params.push(image_url.trim().slice(0, 2*1024*1024));
      updates.push(`owner_image_url=$${params.length}`);
    }
    if (founder_name && founder_name.trim()) {
      params.push(founder_name.trim().slice(0, 100));
      updates.push(`founder_name=$${params.length}`);
    }
    if (founder_avatar_url && isAllowedDirectoryImageUrl(founder_avatar_url)) {
      params.push(founder_avatar_url.trim().slice(0, 2*1024*1024));
      updates.push(`founder_avatar_url=$${params.length}`);
    }
    if (social_twitter && social_twitter.trim()) {
      params.push(social_twitter.trim().slice(0, 300));
      updates.push(`social_twitter=$${params.length}`);
    }
    if (social_linkedin && social_linkedin.trim()) {
      params.push(social_linkedin.trim().slice(0, 300));
      updates.push(`social_linkedin=$${params.length}`);
    }
    if (Array.isArray(screenshots) && screenshots.length > 0) {
      const valid = screenshots.filter(s => typeof s === 'string' && isAllowedDirectoryImageUrl(s));
      if (valid.length > 0) {
        params.push(JSON.stringify(valid.slice(0, 3)));
        updates.push(`screenshots=$${params.length}`);
      }
    }
    if (tech_stack && tech_stack.trim()) {
      params.push(tech_stack.trim().slice(0, 300));
      updates.push(`tech_stack=$${params.length}`);
    }
    const VALID_PLATFORMS = ['Web','iOS','Android','Chrome Extension','API','Desktop'];
    if (platform && VALID_PLATFORMS.includes(platform.trim())) {
      params.push(platform.trim());
      updates.push(`platform=$${params.length}`);
    }
    const VALID_PRICING = ['Free','Freemium','Paid','Open Source'];
    if (pricing_model && VALID_PRICING.includes(pricing_model.trim())) {
      params.push(pricing_model.trim());
      updates.push(`pricing_model=$${params.length}`);
    }
    if (launch_date && /^\d{4}-\d{2}-\d{2}$/.test(launch_date)) {
      params.push(launch_date);
      updates.push(`launch_date=$${params.length}`);
    }

    if (updates.length === 0) {
      await writeSecurityAudit('directory_listing_edit_rejected', {
        actorType: 'owner', listingId: Number(listing_id), actorEmail: claim.owner_email,
        metadata: { reason: 'nothing_to_update' }
      });
      return res.status(400).json({ error: 'nothing_to_update' });
    }

    params.push(listing_id);
    await pool.query(
      `UPDATE directory_listings SET ${updates.join(',')} WHERE id=$${params.length}`,
      params
    );
    const afterState = await getDirectoryListingState(Number(listing_id));
    if (beforeState && afterState) {
      await recordDirectoryListingRevision({
        listingId: Number(listing_id),
        ownerEmail: claim.owner_email,
        revisionType: 'edit',
        before: beforeState,
        after: afterState,
      });
    }
    await writeSecurityAudit('directory_listing_edited', {
      actorType: 'owner',
      listingId: Number(listing_id),
      actorEmail: claim.owner_email,
      metadata: { field_count: updates.length }
    });

    console.log(`[dir-claim/edit] listing ${listing_id} updated by owner (${updates.length} fields)`);
    res.json({ ok: true });
  } catch(err) {
    console.error('[dir-claim/edit]', err.message);
    await writeSecurityAudit('directory_listing_edit_failed', {
      actorType: 'public',
      listingId: Number.isSafeInteger(Number(listing_id)) ? Number(listing_id) : null,
      actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim()) ? String(email).trim().toLowerCase() : null,
      metadata: { reason: String(err.message || err).slice(0, 200) }
    });
    res.status(500).json({ error: 'server_error' });
  }
});

// ── POST /api/directory/claim/relaunch ───────────────────────────────────────
app.post('/api/directory/claim/relaunch', async (req, res) => {
  const { listing_id, email } = req.body || {};
  if (!listing_id)
    return res.status(400).json({ error: 'listing_id required' });
  try {
    const claim = await authorizeDirectoryClaim(req, listing_id, email);
    if (!claim) {
      await writeSecurityAudit('directory_relaunch_rejected', {
        actorType: 'public',
        listingId: Number.isSafeInteger(Number(listing_id)) ? Number(listing_id) : null,
        actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim()) ? String(email).trim().toLowerCase() : null,
        metadata: { reason: 'unauthorized' }
      });
      return res.status(403).json({ error: 'unauthorized' });
    }

    const beforeState = await getDirectoryListingState(Number(listing_id));
    const lr = await pool.query(
      `SELECT submitted_at, name, relaunch_unlimited,
              (relaunch_unlimited=TRUE OR EXISTS (
                SELECT 1 FROM directory_payment_fulfillments dpf
                 WHERE dpf.listing_id=directory_listings.id
                   AND dpf.tier='founder_pack' AND dpf.status='succeeded'
              )) AS founder_pack_entitled
         FROM directory_listings WHERE id=$1 AND status='active'`,
      [listing_id]
    );
    if (!lr.rows.length) {
      await writeSecurityAudit('directory_relaunch_rejected', {
        actorType: 'owner', listingId: Number(listing_id), actorEmail: claim.owner_email,
        metadata: { reason: 'not_found' }
      });
      return res.status(404).json({ error: 'not_found' });
    }

    const daysSince = Math.floor((Date.now() - new Date(lr.rows[0].submitted_at).getTime()) / 86400000);
    if (daysSince < 30 && !lr.rows[0].relaunch_unlimited) {
      await writeSecurityAudit('directory_relaunch_rejected', {
        actorType: 'owner', listingId: Number(listing_id), actorEmail: claim.owner_email,
        metadata: { reason: 'too_soon', days_remaining: 30 - daysSince }
      });
      return res.status(429).json({ error: 'too_soon', days_remaining: 30 - daysSince });
    }

    await pool.query(`UPDATE directory_listings SET submitted_at=NOW() WHERE id=$1`, [listing_id]);
    const afterState = await getDirectoryListingState(Number(listing_id));
    if (lr.rows[0].founder_pack_entitled) {
      await recordDirectoryListingRevision({
        listingId: Number(listing_id),
        ownerEmail: claim.owner_email,
        revisionType: 'relaunch',
        before: beforeState,
        after: afterState,
        metadata: { founder_pack: true },
      });
    }
    await writeSecurityAudit('directory_relaunched', {
      actorType: 'owner', listingId: Number(listing_id), actorEmail: claim.owner_email,
      metadata: { relaunch_unlimited: !!lr.rows[0].relaunch_unlimited, founder_pack: !!lr.rows[0].founder_pack_entitled }
    });
    console.log(`[dir-relaunch] listing ${listing_id} relaunched by ${claim.owner_email}`);
    res.json({ ok: true });
    if (lr.rows[0].founder_pack_entitled) {
      // Relaunch remains fast even when Claude is unavailable or slow. The
      // owner can refresh the panel while this best-effort draft is generated.
      setImmediate(() => generateFounderPackRelaunchDraft(Number(listing_id), claim.owner_email)
        .catch(error => console.error(`[founder-health] draft save failed for listing ${listing_id}:`, error.message)));
    }
  } catch(err) {
    console.error('[dir-claim/relaunch]', err.message);
    await writeSecurityAudit('directory_relaunch_failed', {
      actorType: 'public',
      listingId: Number.isSafeInteger(Number(listing_id)) ? Number(listing_id) : null,
      actorEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim()) ? String(email).trim().toLowerCase() : null,
      metadata: { reason: String(err.message || err).slice(0, 200) }
    });
    res.status(500).json({ error: 'server_error' });
  }
});

