    await pool.query(
      `UPDATE friction_model_leads SET delivered_at=NOW() WHERE email=$1 AND delivered_at IS NULL`,
      [trimmed]
    );

    console.log(`[friction-model] ✓ Guide link sent → ${trimmed}`);
