// This former generated card has no persisted article body. Keep its inbound
// URL useful, but never advertise a redirect/404 as a crawlable article.
const BLOG_LEGACY_REDIRECTS = Object.freeze({
  'saas-directory-submission-2026-best-backlinks': 'saas-directory-submission-2026',
});
async function getLatestReadableBlogPost() {
  try {
    // Do not advertise an auto-generated post unless its body survived restart.
    const { rows } = await pool.query(`
      SELECT slug, title, excerpt, date, read_time
      FROM blog_auto_posts
      WHERE length(trim(content)) > 0
      ORDER BY date DESC, created_at DESC
      LIMIT 1
    `);
    if (rows.length) {
      const post = rows[0];
      const d = new Date(post.date + 'T12:00:00Z');
      return {
        ...post,
        dateLabel: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
          + ' · ' + (post.read_time || 8) + ' min read'
      };
    }
  } catch (e) {
    console.error('[blog-latest] database error:', e.message);
  }
  return BLOG_POSTS[0] || null;
}

app.get('/api/blog/latest', async (req, res) => {
  res.set('Cache-Control', 'no-store, max-age=0');
  res.json(await getLatestReadableBlogPost());
});

// ── GET /api/directory/startup-of-day — daily rotating featured listing ─────
// Picks deterministically from top-100 listings by vote_count using day-of-year
// as seed → changes automatically every midnight UTC, never requires manual update.
// Excludes Founder Pack listings (199,203) so user's own products don't self-feature.
app.get('/api/directory/startup-of-day', async (req, res) => {
  try {
    const dayOfYear = Math.floor((Date.now() - Date.UTC(new Date().getUTCFullYear(), 0, 0)) / 86400000);
    const { rows } = await pool.query(`
      SELECT dl.id, dl.name, dl.url, dl.category, dl.description, dl.vote_count,
             CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                  WHEN dl.image_url IS NOT NULL AND dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                  ELSE NULL END AS image_url
      FROM directory_listings dl
      WHERE dl.status = 'active'
        AND dl.id NOT IN (199, 203)
        AND dl.vote_count >= 10
        AND dl.description IS NOT NULL AND LENGTH(dl.description) > 20
      ORDER BY dl.vote_count DESC
      LIMIT 100
    `);
    if (!rows.length) return res.json({ listing: null });
    const listing = rows[dayOfYear % rows.length];
    res.json({ listing, day: dayOfYear });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── GET /api/directory/startup-of-week — live week winner full detail ────────
// Uses the same computeWinners() cache as the badge system. Returns the listing
// with the most votes since Monday 00:00 UTC. Refreshes every 5 min via cache.
app.get('/api/directory/startup-of-week', async (req, res) => {
  try {
    const winners = await computeWinners();
    if (!winners.week) return res.json({ listing: null });
    const { rows } = await pool.query(`
      SELECT dl.id, dl.name, dl.url, dl.category, dl.description, dl.vote_count,
             CASE WHEN dl.owner_image_url IS NOT NULL THEN '/api/directory/listing-logo/' || dl.id::text
                  WHEN dl.image_url IS NOT NULL AND dl.image_url NOT LIKE '%google.com/s2/favicons%' THEN dl.image_url
                  ELSE NULL END AS image_url,
             (SELECT COUNT(*)::int FROM dir_votes
              WHERE listing_id = dl.id
                AND voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC')) AS week_votes
      FROM directory_listings dl
      WHERE dl.id = $1 AND dl.status = 'active'
    `, [winners.week]);
    if (!rows.length) return res.json({ listing: null });
    res.setHeader('Cache-Control', 'public, max-age=300');
    res.json({ listing: rows[0] });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── GET /api/startup-of-the-week/:id.svg  (and .png alias) ──────────────────
// Generates a branded 1200×630 SVG social card for the given listing.
// Served as image/svg+xml so it works as an og:image and in emails.
app.get('/api/startup-of-the-week/:id.svg', async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!id) return res.status(400).send('Invalid id');
    const { rows } = await pool.query(`
      SELECT dl.id, dl.name, dl.description, dl.vote_count,
             (SELECT COUNT(*)::int FROM dir_votes
              WHERE listing_id = dl.id
                AND voted_at >= date_trunc('week', NOW() AT TIME ZONE 'UTC')) AS week_votes
      FROM directory_listings dl WHERE dl.id = $1 AND dl.status = 'active'
    `, [id]);
    if (!rows.length) return res.status(404).send('Not found');
    const svg = buildStartupOfWeekSvg(rows[0]);
    res.setHeader('Content-Type', 'image/svg+xml');
    res.setHeader('Cache-Control', 'public, max-age=3600');
    res.send(svg);
  } catch(e) { res.status(500).send(e.message); }
});
// PNG alias — serves the same SVG (widely accepted by social crawlers)
app.get('/api/startup-of-the-week/:id.png', async (req, res) => {
  res.redirect(301, `/api/startup-of-the-week/${req.params.id}.svg`);
});

app.get('/blog', async (req, res) => {
  try {
    let html = fs.readFileSync(path.join(__dirname, 'public', 'blog', 'index.html'), 'utf8');
    // Query DB directly — source of truth, works even if in-memory BLOG_POSTS is stale
    const { rows: dbPosts } = await pool.query(
      `SELECT slug, title, excerpt, date, read_time
       FROM blog_auto_posts
       WHERE length(trim(content)) > 0
       ORDER BY date DESC, created_at DESC`
    );
    const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const autoCards = dbPosts
      .filter(p => !BLOG_LEGACY_REDIRECTS[p.slug] && !html.includes(`/blog/${p.slug}`))   // skip redirects and hardcoded posts
      .map(p => {
        const d = new Date(p.date + 'T12:00:00Z');
        const dateStr = d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
        return `\n  <div class="post-card">\n    <a href="/blog/${p.slug}">\n      <div class="post-meta"><span class="post-tag">SEO &amp; Directories</span><span>${dateStr}</span><span>${p.read_time || 8} min read</span></div>\n      <h2>${esc(p.title)}</h2>\n      <p>${esc(p.excerpt)}</p>\n      <span class="post-read">Read article →</span>\n    </a>\n  </div>`;
      }).join('\n');
    if (autoCards) html = html.replace('<div class="posts-grid">', '<div class="posts-grid">' + autoCards);
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store');
    res.send(html);
  } catch(e) {
    console.error('[/blog] render error:', e.message);
    res.sendFile(path.join(__dirname, 'public', 'blog', 'index.html'));
  }
});
app.get('/blog/:slug', async (req, res) => {
  const fs = require('fs');
  // Strip .html suffix if already present so both /blog/foo and /blog/foo.html work
  const slug = req.params.slug.replace(/\.html$/i, '');
  if (slug === 'index') return res.redirect(301, '/blog');
  if (BLOG_LEGACY_REDIRECTS[slug]) {
    return res.redirect(301, `/blog/${BLOG_LEGACY_REDIRECTS[slug]}`);
  }
  const file = path.join(__dirname, 'public', 'blog', slug + '.html');
  if (fs.existsSync(file)) return res.sendFile(file);
  try {
    const { rows } = await pool.query(`
      SELECT slug, title, content, meta_description, keyword, date, read_time
      FROM blog_auto_posts
      WHERE slug=$1 AND length(trim(content)) > 0
      LIMIT 1
    `, [slug]);
    if (rows.length) return res.type('html').send(buildBlogPage(rows[0]));
  } catch (e) {
    console.error('[/blog/:slug] durable post lookup failed:', e.message);
  }
  res.status(404).sendFile(path.join(__dirname, 'public', 'blog', 'index.html'));
});

