const blinkRateLimit = new Map(); // ip → [timestamps]

app.post('/api/blink-test', async (req, res) => {
  // Rate limit: 5 per hour per IP
  const ip  = (req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket.remoteAddress || 'unknown';
  const now = Date.now();
  const hour = 60 * 60 * 1000;
  const recent = (blinkRateLimit.get(ip) || []).filter(t => now - t < hour);
  if (recent.length >= 5) return res.status(429).json({ error: 'limit_reached' });
  recent.push(now);
  blinkRateLimit.set(ip, recent);

  let { content } = req.body;
  if (!content || typeof content !== 'string' || content.trim().length < 8) {
    return res.status(400).json({ error: 'Content too short.' });
  }
  content = content.trim().slice(0, 3000);

  // If URL, fetch and strip to text
  if (/^https?:\/\//i.test(content)) {
    try {
      const urlResp = await safeFetchPublicUrl(content, {
        timeoutMs: 5000,
        maxBytes: 1024 * 1024,
        headers: { 'User-Agent': 'Mozilla/5.0 (compatible; StrategicFlow/1.0)' }
      });
      if (!urlResp.ok) return res.status(400).json({ error: 'Could not fetch URL. Paste the text directly.' });
      const html = await urlResp.text();
      content = html
        // Remove structural chrome wholesale before any text is extracted
        .replace(/<header[\s\S]*?<\/header>/gi, '')
        .replace(/<nav[\s\S]*?<\/nav>/gi, '')
        .replace(/<footer[\s\S]*?<\/footer>/gi, '')
        .replace(/<aside[\s\S]*?<\/aside>/gi, '')
        // Remove common nav/menu containers by id/class pattern
        .replace(/<[^>]+(?:id|class)="[^"]*(?:nav|menu|header|navbar|topbar|site-header|masthead|cookie|banner|gdpr|consent)[^"]*"[^>]*>[\s\S]*?<\/\w+>/gi, '')
        // Strip remaining scripts, styles, then all tags
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 2500);
      if (content.length < 8) return res.status(400).json({ error: 'Could not extract text from URL.' });
    } catch (e) {
      return res.status(400).json({ error: 'Could not fetch URL. Paste the text directly.' });
    }
  }

  const prompt = `You are a conversion expert specializing in the 0.3-second blink test — whether content stops a scroll or gets ignored in a feed or inbox.

── CALIBRATION (mandatory) ──
Use the full scoring range. Realistic distribution: ~25% of content stops the scroll; ~75% gets ignored, but scores spread across 45–85%. Only truly generic or corporate-speak content scores 88–97%. Strong hooks, specific numbers, curiosity gaps, bold value propositions, and compelling opening lines MUST score as "STOPS THE SCROLL". Do NOT cluster everything at 88–97% — that makes the tool useless.

Score bands and corresponding verdicts:
- STOPS THE SCROLL: scroll_past_pct 5–39 (strong hook, specificity, tension, or clear payoff)
- MIXED SIGNAL: scroll_past_pct 40–65 (borderline — some hook but vague, safe, or incomplete; close to a coin flip)
- GETS IGNORED: scroll_past_pct 66–97 (clearly weak — generic, corporate-speak, no hook, boilerplate opener)

── BOILERPLATE FILTER (mandatory) ──
When the input is fetched from a URL, the raw text may include page chrome. You MUST ignore completely and never quote from: cookie consent banners ("this site uses cookies", "accept cookies", "we use cookies"), navigation menu items, breadcrumbs, footer text, legal notices, privacy policy snippets, "skip to content", social share buttons, or any other UI furniture. Only ever quote from the actual headline, email subject line, subheadline, lede sentence, or primary value proposition of the real content.

── OUTPUT ──
Return ONLY a JSON object with exactly these four fields:
- "verdict": "STOPS THE SCROLL", "MIXED SIGNAL", or "GETS IGNORED" — must match the score band above, nothing else
- "scroll_past_pct": integer 1–99 using the calibrated bands above
- "attention_lost_at": a complete, grammatically whole phrase or short sentence (5–15 words) from the REAL content (never boilerplate) — never truncate mid-word or mid-clause; for STOPS THE SCROLL, quote the phrase that hooks most strongly; for MIXED SIGNAL or GETS IGNORED, quote where attention drops
- "reason": one plain-language sentence (max 15 words) — TONE MUST MATCH THE SCORE BAND: positive/reinforcing for low pct (e.g. "Specific number plus named audience creates instant self-selection and curiosity."), diagnostic/cautionary for high pct (e.g. "Generic benefit claim — no specificity or tension."). Never praise content that scored high scroll-past; never criticise content that scored low scroll-past.
- "issue_type": 3–6 word plain-language label — positive label for low pct (e.g. "Strong curiosity gap", "Specific outcome hook"), neutral/negative for high pct (e.g. "Generic value proposition", "Corporate announcement tone", "Vague benefit claim")
- "fix_hint": one sentence (max 13 words) — for low pct: reinforce what is working (e.g. "Keep leading with the specific result to invite self-comparison."); for high pct: concrete directional fix (e.g. "Lead with the outcome the reader gets, not the feature.")

Return only the JSON, nothing else.

Content:
"""
${content}
"""`;

  try {
    const apiResp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: 2000,
        messages: [{ role: 'user', content: prompt }]
      }),
      signal: AbortSignal.timeout(20000)
    });
    const data = await apiResp.json();
    const text = (Array.isArray(data.content) ? data.content.find(b => b.type === 'text')?.text : '') || '';
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) throw new Error('no_json');
    const result = JSON.parse(match[0]);
    if (!result.scroll_past_pct || !result.attention_lost_at) throw new Error('incomplete_json');
    // Derive verdict purely from pct — single source of truth, model's verdict string is ignored
    const pct = Math.min(99, Math.max(1, parseInt(result.scroll_past_pct, 10) || 50));
    const verdict = pct <= 39 ? 'STOPS THE SCROLL' : pct <= 65 ? 'MIXED SIGNAL' : 'GETS IGNORED';
    res.json({
      verdict,
      pct,
      lostAt:     String(result.attention_lost_at).slice(0, 120),
      reason:     result.reason     ? String(result.reason).slice(0, 200)     : '',
      issueType:  result.issue_type ? String(result.issue_type).slice(0, 80)  : '',
      fixHint:    result.fix_hint   ? String(result.fix_hint).slice(0, 200)   : ''
    });
  } catch (err) {
    console.error('[blink-test] error:', err.message);
    res.status(500).json({ error: 'Analysis failed. Please try again.' });
  }
});

